    struct GameplayTag
    {
        FName tag_name{};
    };

    struct GameplayTagContainer
    {
        TArray<GameplayTag> gameplay_tags{};
        TArray<GameplayTag> parent_tags{};
    };

    static_assert(sizeof(GameplayTag) == 8);
    static_assert(sizeof(GameplayTagContainer) == 32);

    struct TargetSpec
    {
        const RC::Unreal::TCHAR* asset_name;

        // Exact compile-time policy. Only named NPC-style humanoid heads below
        // opt in. Their CPD Hair/Eyebrow slot locks are neutralized. At render
        // time the already event-captured Face.Mesh component is also checked
        // locally for embedded Hair/Eyebrow material sections and only those
        // sections are hidden. No UObject/world/component enumeration.
        bool unlock_hair_and_eyebrows{};
    };

    // 74 face-menu targets:
    // 57 humanoid/alien FACE-ONLY CPDs + 17 genuine Astromech Head.Mesh CPDs.
    // NPC hair/facial-hair is never a separate Face.Mesh catalogue entry; hair remains
    // in its own exact static catalogue. Named NPC-style entries opt into the exact
    // unlock_hair_and_eyebrows policy below. The policy strips ONLY their Hair.Hair.Mesh
    // / Head.Eyebrow.Mesh entries from OverrideSlots, LockedSlots and HiddenSlots.
    // Separately, when one of the already-captured Face.Mesh components renders a head
    // whose own material list contains embedded Hair/Eyebrow geometry (Anakin proves
    // this layout), those material sections are hidden locally with ShowMaterialSection.
    // No game-object/world/component enumeration is used.
    //
    // EXP11 keeps the 22 paint CPDs in their native Primary / Tertiary /
    // Quaternary slots, but hoists those slots into the active HUMANOID HEAD
    // STRUCTURAL CONTAINER (clothing-style hierarchy). They are no longer
    // grafted into the 17 leaf head CPDs.
    //
    // The 17 real geometry choices use an independent direct instance loaded
    // only from the seven exact SkeletalMesh paths below. This clean build never scans the
    // world for Astromech geometry. The game-managed Humanoid Face.Mesh is used
    // only as an event-captured selection/material proxy and is collapsed to
    // 0.001 while the independent clone is active.
    constexpr std::size_t kHumanoidFaceTargetCount = 57;
    constexpr std::size_t kAstromechHeadTargetCount = 17;

