    // ---------------------------------------------------------------------
    // Static non-clothing Appearance database
    // ---------------------------------------------------------------------
    // Generated from the user-provided Expanded Wardrobe 2.2.0 reverse-
    // engineering report. Runtime NEVER scans game assets to discover these
    // entries: every exact CPD name, slot recipe and compatibility recipe is
    // embedded in this DLL.
    //
    // Descriptor low 16 bits = source slot index from the reference manifest.
    // CompatibilityMask = exact temporary gameplay tags required by the CPD.
    // Selectors = up to 3 exact AuthoredOnly / NPC-name tags (0xFF = none).
    struct AppearanceManifestSpec
    {
        const RC::Unreal::TCHAR* asset_name;
        std::uint64_t descriptor;
        std::uint64_t compatibility_mask;
        std::uint64_t selectors;
    };

