    struct UniquePatternResult
    {
        std::uintptr_t address{};
        std::size_t matches{};
    };

    template <std::size_t N>
    auto find_unique_executable_pattern(
        const RuntimeIdentity& runtime,
        const std::array<std::uint8_t, N>& bytes,
        const std::array<bool, N>& exact) -> UniquePatternResult
    {
        UniquePatternResult result{};

        if (runtime.base == 0 ||
            runtime.image_size < bytes.size())
        {
            return result;
        }

        const auto* dos =
            reinterpret_cast<const IMAGE_DOS_HEADER*>(runtime.base);
        const auto* nt =
            reinterpret_cast<const IMAGE_NT_HEADERS64*>(
                runtime.base +
                static_cast<std::uintptr_t>(dos->e_lfanew));

        const auto* section =
            IMAGE_FIRST_SECTION(nt);

        for (std::uint16_t section_index = 0;
             section_index < nt->FileHeader.NumberOfSections;
             ++section_index, ++section)
        {
            if ((section->Characteristics &
                 IMAGE_SCN_MEM_EXECUTE) == 0)
            {
                continue;
            }

            const auto begin =
                runtime.base +
                static_cast<std::uintptr_t>(
                    section->VirtualAddress);

            const auto section_size =
                static_cast<std::uintptr_t>(
                    std::max(
                        section->Misc.VirtualSize,
                        section->SizeOfRawData));

            if (section_size < bytes.size() ||
                begin < runtime.base ||
                begin + section_size >
                    runtime.base + runtime.image_size)
            {
                continue;
            }

            for (std::uintptr_t offset = 0;
                 offset + bytes.size() <= section_size;
                 ++offset)
            {
                const auto* candidate =
                    reinterpret_cast<const std::uint8_t*>(
                        begin + offset);

                bool match = true;

                for (std::size_t i = 0;
                     i < bytes.size();
                     ++i)
                {
                    if (exact[i] &&
                        candidate[i] != bytes[i])
                    {
                        match = false;
                        break;
                    }
                }

                if (!match)
                {
                    continue;
                }

                ++result.matches;

                if (result.matches == 1)
                {
                    result.address =
                        begin + offset;
                }
                else
                {
                    // Fail closed on ambiguity.
                    result.address = 0;
                }
            }
        }

        return result;
    }

    struct CompatibleHookTarget
    {
        std::uintptr_t address{};
        bool chained{};
    };

    auto is_executable_address(std::uintptr_t address) -> bool
    {
        if (address == 0)
        {
            return false;
        }

        MEMORY_BASIC_INFORMATION info{};
        if (::VirtualQuery(reinterpret_cast<const void*>(address),
                           &info, sizeof(info)) == 0 ||
            info.State != MEM_COMMIT ||
            (info.Protect & PAGE_GUARD) != 0 ||
            (info.Protect & PAGE_NOACCESS) != 0)
        {
            return false;
        }

        const DWORD executable =
            PAGE_EXECUTE |
            PAGE_EXECUTE_READ |
            PAGE_EXECUTE_READWRITE |
            PAGE_EXECUTE_WRITECOPY;

        return (info.Protect & executable) != 0;
    }

    auto resolve_compatible_hook_target(
        std::uintptr_t rva,
        const std::array<std::uint8_t, 16>& expected)
        -> CompatibleHookTarget
    {
        if (g_runtime.base == 0 ||
            rva + expected.size() > g_runtime.image_size)
        {
            return {};
        }

        const auto entry = g_runtime.base + rva;

        if (std::memcmp(reinterpret_cast<const void*>(entry),
                        expected.data(), expected.size()) == 0)
        {
            return {entry, false};
        }

        // ZCUnlocked's native detour writer uses exactly:
        //   FF 25 00 00 00 00
        //   <8-byte absolute destination>
        // If those bytes are present, hook the destination function instead.
        // Flow then becomes:
        // game -> ZCUnlocked hook -> our hook -> ZC trampoline -> original,
        // while our trampoline preserves ZCUnlocked's hook body.
        const auto* bytes =
            reinterpret_cast<const std::uint8_t*>(entry);

        if (bytes[0] == 0xFF &&
            bytes[1] == 0x25 &&
            bytes[2] == 0x00 &&
            bytes[3] == 0x00 &&
            bytes[4] == 0x00 &&
            bytes[5] == 0x00)
        {
            std::uintptr_t destination{};
            std::memcpy(&destination, bytes + 6, sizeof(destination));

            if (is_executable_address(destination))
            {
                return {destination, true};
            }
        }

        return {};
    }

    auto names_equal(const FName& a, const FName& b) -> bool
    {
        return std::memcmp(&a, &b, sizeof(FName)) == 0;
    }

    auto ids_equal(const FPrimaryAssetId& a, const FPrimaryAssetId& b) -> bool
    {
        return std::memcmp(&a, &b, sizeof(FPrimaryAssetId)) == 0;
    }

    auto container_has_exact_tag(const GameplayTagContainer& container,
                                 const GameplayTag& tag) -> bool
    {
        const auto contains = [&tag](const TArray<GameplayTag>& tags)
        {
            for (const auto& candidate : tags)
            {
                if (names_equal(candidate.tag_name, tag.tag_name))
                {
                    return true;
                }
            }
            return false;
        };

        return contains(container.gameplay_tags) ||
               contains(container.parent_tags);
    }

    auto array_contains(const TArray<FPrimaryAssetId>& ids,
                        const FPrimaryAssetId& target) -> bool
    {
        for (const auto& id : ids)
        {
            if (ids_equal(id, target))
            {
                return true;
            }
        }
        return false;
    }

    auto target_index(const FPrimaryAssetId& id) -> std::size_t
    {
        for (std::size_t i = 0; i < g_target_ids.size(); ++i)
        {
            if (ids_equal(id, g_target_ids[i]))
            {
                return i;
            }
        }
        return g_target_ids.size();
    }


    auto manifest_index_is_clothing_excluded(std::size_t index) -> bool
    {
        for (const auto excluded : kExcludedClothingManifestIndices)
        {
            if (index == excluded)
            {
                return true;
            }
        }
        return false;
    }

    auto compare_primary_asset_ids(
        const FPrimaryAssetId& a,
        const FPrimaryAssetId& b) -> int
    {
        return std::memcmp(&a, &b, sizeof(FPrimaryAssetId));
    }

    auto find_manifest_index(const FPrimaryAssetId& id) -> std::size_t
    {
        std::size_t first = 0;
        std::size_t last = g_manifest_lookup_order.size();

        while (first < last)
        {
            const auto middle = first + ((last - first) / 2);
            const auto manifest_index = g_manifest_lookup_order[middle];
            const auto cmp =
                compare_primary_asset_ids(
                    g_manifest_ids[manifest_index],
                    id);

            if (cmp < 0)
            {
                first = middle + 1;
            }
            else
            {
                last = middle;
            }
        }

        if (first >= g_manifest_lookup_order.size())
        {
            return g_manifest_ids.size();
        }

        const auto candidate = g_manifest_lookup_order[first];
        return ids_equal(g_manifest_ids[candidate], id)
            ? candidate
            : g_manifest_ids.size();
    }

    auto try_manifest_requirements(
        const FPrimaryAssetId& id,
        const GameplayTagContainer& owned_tags,
        std::size_t manifest_index) -> bool
    {
        if (!kEnableStaticAppearanceManifest ||
            manifest_index >= kAppearanceManifestCount ||
            manifest_index_is_clothing_excluded(manifest_index) ||
            g_does_part_trampoline == 0)
        {
            return false;
        }

        alignas(GameplayTagContainer)
            std::array<std::byte, sizeof(GameplayTagContainer)> storage{};

        auto* adapted =
            reinterpret_cast<GameplayTagContainer*>(storage.data());

        const auto copy_ctor =
            reinterpret_cast<GameplayTagContainerCopyCtorFunction>(
                g_runtime.base + kGameplayTagContainerCopyCtorRva);

        const auto destructor =
            reinterpret_cast<GameplayTagContainerDtorFunction>(
                g_runtime.base + kGameplayTagContainerDtorRva);

        const auto add_tag =
            reinterpret_cast<GameplayTagContainerAddTagFunction>(
                g_runtime.base + kGameplayTagContainerAddTagRva);

        const auto original =
            reinterpret_cast<DoesPartMeetRequirementsFunction>(
                g_does_part_trampoline);

        if (!copy_ctor || !destructor || !add_tag || !original)
        {
            return false;
        }

        copy_ctor(adapted, &owned_tags);

        const auto& spec = kAppearanceManifestSpecs[manifest_index];

        // Up to 3 exact selector tags: AuthoredOnly / NPC name.
        for (std::size_t byte_index = 0; byte_index < 3; ++byte_index)
        {
            const auto selector =
                static_cast<std::uint8_t>(
                    (spec.selectors >> (byte_index * 8)) & 0xFFULL);

            if (selector == 0xFF)
            {
                continue;
            }

            if (selector >= g_appearance_selector_tags.size() ||
                g_appearance_selector_tags[selector].tag_name.IsNone())
            {
                destructor(adapted);
                return false;
            }

            add_tag(adapted, &g_appearance_selector_tags[selector]);
        }

        // Exact per-CPD compatibility recipe from the static manifest.
        for (std::size_t bit = 0;
             bit < g_appearance_compatibility_tags.size();
             ++bit)
        {
            if ((spec.compatibility_mask & (1ULL << bit)) == 0)
            {
                continue;
            }

            const auto& tag = g_appearance_compatibility_tags[bit];
            if (tag.tag_name.IsNone())
            {
                destructor(adapted);
                return false;
            }

            add_tag(adapted, &tag);
        }

        const bool result = original(&id, adapted);
        destructor(adapted);
        return result;
    }

    auto append_manifest_id_if_missing(
        TArray<FPrimaryAssetId>& output,
        std::size_t manifest_index) -> bool
    {
        if (manifest_index >= g_manifest_ids.size() ||
            manifest_index_is_clothing_excluded(manifest_index))
        {
            return false;
        }

        const auto& id = g_manifest_ids[manifest_index];

        if (array_contains(output, id))
        {
            return false;
        }

        output.Add(id);
        return true;
    }

    auto manifest_index_is_curated_exposed(
        std::size_t manifest_index) -> bool
    {
        if (manifest_index >= kAppearanceManifestCount ||
            manifest_index_is_clothing_excluded(manifest_index))
        {
            return false;
        }

        for (const auto candidate : kStaticCatalogueManifestIndices)
        {
            if (candidate == manifest_index)
            {
                return true;
            }
        }

        for (const auto& choice : kStaticHairChoices)
        {
            if (choice.generic_manifest_index == manifest_index ||
                choice.devaronian_manifest_index == manifest_index)
            {
                return true;
            }
        }

        for (const auto& choice : kStaticFacialHairChoices)
        {
            if (choice.generic_manifest_index == manifest_index ||
                choice.devaronian_manifest_index == manifest_index)
            {
                return true;
            }
        }

        // Eyes are deliberately NOT injected into Face.Mesh anymore. They are
        // exposed only when the real vanilla eye catalogue is detected by an
        // exact-ID anchor in Hook_FilterAssetDataByTags.
        if (manifest_index >= kEyeManifestStart &&
            manifest_index < kEyeManifestEnd)
        {
            return true;
        }

        return false;
    }

    auto manifest_index_allows_exact_crossrace_force(
        std::size_t manifest_index) -> bool
    {
        if (!manifest_index_is_curated_exposed(manifest_index))
        {
            return false;
        }

        // SkinTone is already working exactly as desired in exp1. Freeze that
        // behaviour: do not add a new unconditional fallback to this family.
        constexpr std::uint16_t kSkinToneSlotIndex = 24;

        const auto source_slot =
            static_cast<std::uint16_t>(
                kAppearanceManifestSpecs[manifest_index].descriptor &
                0xFFFFULL);

        return source_slot != kSkinToneSlotIndex;
    }

    template <std::size_t N>
    auto output_contains_any(
        const TArray<FPrimaryAssetId>& output,
        const std::array<FPrimaryAssetId, N>& ids) -> bool
    {
        for (const auto& id : ids)
        {
            if (array_contains(output, id))
            {
                return true;
            }
        }
        return false;
    }


    constexpr std::array<std::size_t, 7>
        kHelmetBridgeManifestIndices{{
        752, 753, 754, 755, 756, 757, 758
    }};

    auto output_contains_known_helmet_anchor(
        const TArray<FPrimaryAssetId>& output) -> bool
    {
        for (const auto manifest_index : kHelmetBridgeManifestIndices)
        {
            if (manifest_index < g_manifest_ids.size() &&
                array_contains(output, g_manifest_ids[manifest_index]))
            {
                return true;
            }
        }

        return false;
    }

    auto append_known_alien_helmet_bridge(
        TArray<FPrimaryAssetId>& output) -> std::size_t
    {
        std::size_t added = 0;

        // These seven exact IDs were deliberately excluded from the normal
        // non-clothing static catalogue. EXP6 uses them ONLY after a real
        // Helmet catalogue has been positively identified.
        for (const auto manifest_index : kHelmetBridgeManifestIndices)
        {
            if (manifest_index >= g_manifest_ids.size())
            {
                continue;
            }

            const auto& id = g_manifest_ids[manifest_index];
            if (array_contains(output, id))
            {
                continue;
            }

            output.Add(id);
            ++added;
        }

        return added;
    }

    auto remember_observed_helmet_catalogue(
        const TArray<FPrimaryAssetId>& output) -> void
    {
        std::lock_guard<std::mutex> guard{
            g_observed_helmet_catalogue_mutex};

        for (const auto& id : output)
        {
            bool known = false;
            for (const auto& cached : g_observed_helmet_catalogue_ids)
            {
                if (ids_equal(cached, id))
                {
                    known = true;
                    break;
                }
            }

            if (!known)
            {
                g_observed_helmet_catalogue_ids.push_back(id);
            }
        }

        g_helmet_catalogue_count.store(
            g_observed_helmet_catalogue_ids.size(),
            std::memory_order_release);

        if (!g_helmet_catalogue_seen.exchange(
                true, std::memory_order_relaxed))
        {
            g_helmet_catalogue_pending.store(
                true, std::memory_order_release);
        }
    }

    auto is_observed_helmet_candidate(
        const FPrimaryAssetId& id) -> bool
    {
        std::lock_guard<std::mutex> guard{
            g_observed_helmet_catalogue_mutex};

        for (const auto& cached : g_observed_helmet_catalogue_ids)
        {
            if (ids_equal(cached, id))
            {
                return true;
            }
        }

        return false;
    }

    auto append_static_slot_range_raw(
        std::size_t donor_slot_index,
        TArray<FPrimaryAssetId>& output) -> std::size_t
    {
        if (donor_slot_index >= kStaticCatalogueRanges.size())
        {
            return 0;
        }

        const auto range = kStaticCatalogueRanges[donor_slot_index];
        std::size_t added = 0;

        for (std::size_t offset = 0; offset < range.count; ++offset)
        {
            const auto flat_index =
                static_cast<std::size_t>(range.start) + offset;

            if (flat_index >= kStaticCatalogueManifestIndices.size())
            {
                break;
            }

            if (append_manifest_id_if_missing(
                    output,
                    kStaticCatalogueManifestIndices[flat_index]))
            {
                ++added;
            }
        }

        return added;
    }

    auto is_devaronian_context(
        const GameplayTagContainer& owned_tags) -> bool
    {
        constexpr std::size_t kDevaronianCompatibilityBit = 16;

        return kDevaronianCompatibilityBit <
                   g_appearance_compatibility_tags.size() &&
               container_has_exact_tag(
                   owned_tags,
                   g_appearance_compatibility_tags[
                       kDevaronianCompatibilityBit]);
    }

    auto is_zabrak_context(
        const GameplayTagContainer& owned_tags) -> bool
    {
        constexpr std::size_t kZabrakCompatibilityBit = 33;

        return kZabrakCompatibilityBit <
                   g_appearance_compatibility_tags.size() &&
               container_has_exact_tag(
                   owned_tags,
                   g_appearance_compatibility_tags[
                       kZabrakCompatibilityBit]);
    }

    template <std::size_t N>
    auto append_variant_catalogue(
        const std::array<VariantChoice, N>& choices,
        const GameplayTagContainer& owned_tags,
        TArray<FPrimaryAssetId>& output) -> std::size_t
    {
        const bool devaronian = is_devaronian_context(owned_tags);
        std::size_t added = 0;

        for (const auto& choice : choices)
        {
            std::size_t manifest_index =
                choice.generic_manifest_index;

            if (devaronian &&
                choice.devaronian_manifest_index != kNoManifestIndex)
            {
                manifest_index =
                    choice.devaronian_manifest_index;
            }

            if (append_manifest_id_if_missing(
                    output, manifest_index))
            {
                ++added;
            }
        }

        return added;
    }

    auto append_hair_catalogue(
        const GameplayTagContainer& owned_tags,
        TArray<FPrimaryAssetId>& output) -> std::size_t
    {
        const bool devaronian =
            is_devaronian_context(owned_tags);

        const bool zabrak =
            is_zabrak_context(owned_tags);

        std::size_t added = 0;

        for (const auto& choice : kStaticHairChoices)
        {
            std::size_t manifest_index =
                choice.generic_manifest_index;

            // The 25 paired Devaronian variants are authored in the genuine
            // Hair.Hair.Mesh slot. Their generic Human twins come from the
            // reference mod's Face.Mesh manifest and were the strongest
            // suspect for "visible card, no effect" on Zabrak. For Zabrak,
            // prefer the slot-correct Devaronian geometry whenever it exists.
            if ((devaronian || zabrak) &&
                choice.devaronian_manifest_index != kNoManifestIndex)
            {
                manifest_index =
                    choice.devaronian_manifest_index;
            }

            // For Zabrak, do not deliberately inject a Face.Mesh-authored
            // "Hair" CPD into Hair.Hair.Mesh when no slot-correct variant is
            // known. Keep genuine slot-28 entries (None + Rodian/Weequay/etc.)
            // and the paired Devaronian styles only.
            if (zabrak)
            {
                const auto source_slot =
                    static_cast<std::uint16_t>(
                        kAppearanceManifestSpecs[manifest_index].descriptor &
                        0xFFFFULL);

                if (source_slot != 28)
                {
                    continue;
                }
            }

            if (append_manifest_id_if_missing(
                    output, manifest_index))
            {
                ++added;
            }
        }

        return added;
    }


    constexpr std::uint64_t kAstromechSpecificRigCompatibilityMask =
        (1ULL << 7) |  // BR1
        (1ULL << 8) |  // R2
        (1ULL << 9) |  // R3
        (1ULL << 10) | // R4
        (1ULL << 11);  // R5

    auto active_astromech_specific_rig_mask(
        const GameplayTagContainer& owned_tags) -> std::uint64_t
    {
        std::uint64_t mask = 0;

        for (std::size_t bit = 7; bit <= 11; ++bit)
        {
            if (bit < g_appearance_compatibility_tags.size() &&
                container_has_exact_tag(
                    owned_tags,
                    g_appearance_compatibility_tags[bit]))
            {
                mask |= (1ULL << bit);
            }
        }

        return mask;
    }

    auto append_astromech_head_color_catalogue(
        std::size_t slot_index,
        const GameplayTagContainer& owned_tags,
        TArray<FPrimaryAssetId>& output) -> std::size_t
    {
        if (slot_index < 4 ||
            slot_index > 6 ||
            slot_index >= kStaticCatalogueRanges.size())
        {
            return 0;
        }

        const auto owned_rigs =
            active_astromech_specific_rig_mask(owned_tags);
        const auto visual_rigs =
            g_active_astromech_visual_rig_mask.load(
                std::memory_order_acquire);

        const auto active_rigs =
            owned_rigs != 0
                ? owned_rigs
                : visual_rigs;

        const auto paint_probe_index =
            slot_index - 4;

        if (paint_probe_index <
                g_astromech_paint_ui_request_seen.size() &&
            !g_astromech_paint_ui_request_seen[paint_probe_index].exchange(
                true, std::memory_order_acq_rel))
        {
            RC::Output::send<RC::LogLevel::Verbose>(
                STR("[TheseArentTheHeadsYoureLookingFor] astro_paint_ui_request slot_index={} slot={} owned_rigs={} visual_rigs={} active_rigs={} structural_roots_patched={}\n"),
                slot_index,
                kAppearanceSlotNames[slot_index],
                owned_rigs,
                visual_rigs,
                active_rigs,
                g_astromech_paint_structural_roots_patched.load(
                    std::memory_order_acquire));
        }

        // Clothing-style gating: when no Astromech rig is selected this child
        // field has no options. On R2/R4/R5/BR1/etc. only matching paint CPDs
        // are offered. The EXP11 UI probe above tells us whether the UI reaches
        // these selectors at all; EXP10 never emitted slot 4/5/6 catalogue logs.
        if (active_rigs == 0)
        {
            return 0;
        }

        const auto range =
            kStaticCatalogueRanges[slot_index];

        std::size_t added = 0;

        for (std::size_t offset = 0;
             offset < range.count;
             ++offset)
        {
            const auto flat_index =
                static_cast<std::size_t>(range.start) + offset;

            if (flat_index >= kStaticCatalogueManifestIndices.size())
            {
                break;
            }

            const auto manifest_index =
                static_cast<std::size_t>(
                    kStaticCatalogueManifestIndices[flat_index]);

            if (manifest_index >= kAppearanceManifestSpecs.size())
            {
                continue;
            }

            const auto entry_rigs =
                kAppearanceManifestSpecs[manifest_index].
                    compatibility_mask &
                kAstromechSpecificRigCompatibilityMask;

            // Keep only paint recipes authored for the active Astromech rig.
            if (active_rigs != 0 &&
                entry_rigs != 0 &&
                (entry_rigs & active_rigs) == 0)
            {
                continue;
            }

            if (append_manifest_id_if_missing(
                    output,
                    manifest_index))
            {
                ++added;
            }
        }

        return added;
    }

    auto append_static_catalogue_for_slot(
        std::size_t slot_index,
        const GameplayTagContainer& owned_tags,
        TArray<FPrimaryAssetId>& output) -> std::size_t
    {
        if (slot_index >= kStaticCatalogueRanges.size())
        {
            return 0;
        }

        // EXP11: native Astromech paint fields. These are genuine CPD colour
        // slots, not Face.Mesh entries. Prefer the currently selected
        // Astromech rig when the game's owned-tag context exposes it.
        if (slot_index >= 4 && slot_index <= 6)
        {
            return append_astromech_head_color_catalogue(
                slot_index,
                owned_tags,
                output);
        }

        // Hair / Facial Hair are logical deduplicated catalogues.
        if (slot_index == 27)
        {
            return append_variant_catalogue(
                kStaticFacialHairChoices,
                owned_tags,
                output);
        }

        if (slot_index == 28)
        {
            return append_hair_catalogue(
                owned_tags,
                output);
        }

        const auto range =
            kStaticCatalogueRanges[slot_index];

        std::size_t added = 0;

        for (std::size_t offset = 0;
             offset < range.count;
             ++offset)
        {
            const auto flat_index =
                static_cast<std::size_t>(range.start) + offset;

            if (flat_index >= kStaticCatalogueManifestIndices.size())
            {
                break;
            }

            if (append_manifest_id_if_missing(
                    output,
                    kStaticCatalogueManifestIndices[flat_index]))
            {
                ++added;
            }
        }

        return added;
    }

    auto try_graft_missing_hair_roots() -> void;
    auto try_neutralize_loaded_devaronian_face_overrides() -> std::size_t;
    auto request_devaronian_face_patch_window() -> void;
    auto try_sanitize_static_npc_face_target(std::size_t target_index) -> bool;
    auto try_sanitize_static_npc_face_overrides() -> std::size_t;
    auto request_static_npc_face_sanitize_window() -> void;
    auto request_astromech_paint_graft_window() -> void;
    auto try_graft_astromech_paint_slots_immediate() -> void;

    // EXP6 intentionally removed the broad OwnedGameplayTags hook.

    auto hook_does_part_meet_requirements(
        const FPrimaryAssetId* id,
        const GameplayTagContainer* owned_tags) -> bool
    {
        const auto original =
            reinterpret_cast<DoesPartMeetRequirementsFunction>(
                g_does_part_trampoline);

        if (!original || !id || !owned_tags)
        {
            return false;
        }

        const auto requested_target_index =
            target_index(*id);

        if (requested_target_index < kHumanoidFaceTargetCount &&
            requested_target_index < kTargetSpecs.size() &&
            kTargetSpecs[requested_target_index].unlock_hair_and_eyebrows)
        {
            // Exact compile-time NPC head policy. Resolve/patch this one CPD
            // directly before vanilla consumes its slot overrides. Also wake
            // the tiny event-captured Face.Mesh list so embedded Hair/Eyebrow
            // render sections are hidden as soon as the selected mesh arrives.
            (void)try_sanitize_static_npc_face_target(
                requested_target_index);
            request_static_npc_face_sanitize_window();
            g_visual_dirty.store(
                true, std::memory_order_release);
            g_visual_rebuild_event.store(
                true, std::memory_order_release);
        }

        if (requested_target_index >= kHumanoidFaceTargetCount &&
            requested_target_index < kTargetSpecs.size())
        {
            // Cheap selection/validation wake. If this is just catalogue
            // enumeration the atomic events coalesce; if it is an applied Astro
            // choice it shortens the time before the authored 90-degree source
            // is collapsed.
            g_visual_dirty.store(
                true, std::memory_order_release);
            g_visual_rebuild_event.store(
                true, std::memory_order_release);
        }

        // The four Devaronian face CPDs carry exact OverrideSlots/HiddenSlots
        // fragments. Request a short exact-path patch window as soon as one of
        // them enters the validation path; also attempt synchronously.
        for (std::size_t i = 0;
             i < g_devaronian_face_ids.size();
             ++i)
        {
            if (ids_equal(*id, g_devaronian_face_ids[i]))
            {
                request_devaronian_face_patch_window();
                break;
            }
        }

        // Structural Hair CPDs are intentionally recognized BEFORE vanilla so
        // the exact six-item exception is deterministic even when another
        // compatibility mod in the chain would otherwise answer differently.
        // This also gives us an unambiguous log proving whether the nested Hair
        // build path actually validates these container IDs.
        for (std::size_t i = 0;
             i < g_hair_architecture_ids.size();
             ++i)
        {
            if (!ids_equal(*id, g_hair_architecture_ids[i]))
            {
                continue;
            }

            if (!g_hair_arch_force_seen[i].exchange(
                    true, std::memory_order_relaxed))
            {
                g_hair_arch_force_pending[i].store(
                    true, std::memory_order_release);
            }

            return true;
        }

        if (original(id, owned_tags))
        {
            return true;
        }

        // EXP6 helmet bypass: candidate-scoped, not tag-scoped. The ID must
        // have been observed in a catalogue positively identified as Helmet
        // by native Togruta/Twi'lek helmet anchors. This keeps clipping
        // allowed without turning every CustomizationPartDefinition into a
        // valid helmet.
        if (is_observed_helmet_candidate(*id))
        {
            if (!g_helmet_requirement_bypass_seen.exchange(
                    true, std::memory_order_relaxed))
            {
                g_helmet_requirement_bypass_pending.store(
                    true, std::memory_order_release);
            }

            return true;
        }

        // Preserve the curated 74-head behaviour. EXP9 keeps only 17 genuine
        // Astromech Head.Mesh CPDs in Humanoid Face.Mesh; the 22 paint CPDs
        // now live in their native color slots.
        if (target_index(*id) < kTargetSpecs.size())
        {
            return true;
        }

        // Whole-species roots are outside the 822 Appearance slot manifest.
        for (const auto& species_id : g_hidden_species_ids)
        {
            if (ids_equal(*id, species_id))
            {
                return true;
            }
        }

        // Every other unlock is exact-ID only. No broad all-species retry.
        const auto manifest_index =
            find_manifest_index(*id);

        if (manifest_index >= g_manifest_ids.size())
        {
            return false;
        }

        if (try_manifest_requirements(
                *id,
                *owned_tags,
                manifest_index))
        {
            return true;
        }

        // EXP2 diagnostic/compatibility fallback: exact curated IDs only.
        // This deliberately answers one question: when a cross-race item is
        // visible but clicking it is rejected, is DoesPartMeetRequirements the
        // last barrier? There is still NO global validation bypass and no
        // persistent mutation of the character's owned tags.
        if (manifest_index_allows_exact_crossrace_force(
                manifest_index))
        {
            if (!g_exact_force_seen[manifest_index].exchange(
                    true, std::memory_order_relaxed))
            {
                g_exact_force_pending[manifest_index].store(
                    true, std::memory_order_release);
                g_exact_force_log_dirty.store(
                    true, std::memory_order_release);
            }

            return true;
        }

        return false;
    }

    auto hook_filter_asset_data_by_tags(
        void* subsystem,
        const GameplayTagContainer* owned_tags,
        TArray<FPrimaryAssetId>* output) -> void
    {
        const auto original =
            reinterpret_cast<FilterAssetDataByTagsFunction>(
                g_filter_trampoline);

        if (!original)
        {
            return;
        }

        // EXP11: determine Face.Mesh context BEFORE vanilla builds the catalogue.
        // This gives the three Astromech paint selectors their earliest possible
        // chance to exist in the humanoid Head structure before UI traversal.
        const bool is_face_catalogue_request =
            owned_tags != nullptr &&
            container_has_exact_tag(
                *owned_tags,
                g_face_slot_tag);

        if (is_face_catalogue_request)
        {
            try_graft_astromech_paint_slots_immediate();
        }

        // Exactly one vanilla catalogue build. Everything the mod adds after
        // this point comes from compile-time exact-ID tables.
        original(subsystem, owned_tags, output);

        // EXP6 CPU guard: Astromech visuals only need a fast rebuild window
        // when the Face.Mesh catalogue is involved. EXP5 woke a global
        // SkeletalMeshComponent scan for EVERY customization catalogue call
        // (tattoos, hair, colours...), which is unnecessary.
        if (is_face_catalogue_request)
        {
            g_visual_dirty.store(
                true, std::memory_order_release);
            g_visual_rebuild_event.store(
                true, std::memory_order_release);

            // If startup happened before AssetManager could resolve the native
            // Astromech Head container, opening Face.Mesh gives EXP9 another
            // bounded chance to graft the three paint selectors.
            request_astromech_paint_graft_window();
        }

        // Face-menu requests are another exact, bounded opportunity to
        // neutralize any Devaronian face CPD that is already loaded.
        if (owned_tags != nullptr &&
            container_has_exact_tag(
                *owned_tags,
                g_face_slot_tag))
        {
            (void)try_neutralize_loaded_devaronian_face_overrides();
        }

        if (!owned_tags || !output)
        {
            return;
        }

        // EXP3 eye routing:
        // The reference manifest places CPD_H_Eyes_* in Face.Mesh, but EXP1
        // proved that blindly injecting them there creates dead entries. Do
        // not guess a new slot tag. Instead, recognize the REAL vanilla eye
        // catalogue by one of its own exact eye IDs already present in the
        // original result, then append the remaining compiled eye IDs to that
        // same catalogue. This is contextual routing, not an asset scan.
        bool is_eye_catalogue = false;

        for (std::size_t i = kEyeManifestStart;
             i < kEyeManifestEnd;
             ++i)
        {
            if (array_contains(*output, g_manifest_ids[i]))
            {
                is_eye_catalogue = true;
                break;
            }
        }

        if (is_eye_catalogue)
        {
            std::size_t eye_added = 0;

            for (std::size_t i = kEyeManifestStart;
                 i < kEyeManifestEnd;
                 ++i)
            {
                if (append_manifest_id_if_missing(*output, i))
                {
                    ++eye_added;
                }
            }

            if (!g_eye_catalogue_seen.exchange(
                    true, std::memory_order_relaxed))
            {
                g_eye_catalogue_added.store(
                    eye_added, std::memory_order_release);
                g_eye_catalogue_pending.store(
                    true, std::memory_order_release);
            }
        }


        // EXP6: identify a real helmet catalogue by exact native alien helmet
        // anchors, then remember EVERY candidate returned by the chained
        // vanilla/ZCUnlocked catalogue. This gives the requirements hook a
        // precise candidate allow-list without depending on guessed slot tags.
        if (output_contains_known_helmet_anchor(*output))
        {
            (void)append_known_alien_helmet_bridge(*output);
            remember_observed_helmet_catalogue(*output);
        }

        // EXP6 local Togruta face-tattoo bridge. Togruta has its own
        // Head.Markings tree while generic humanoids expose BodyArt.Tattoo.
        // When the actual request is a Togruta Head.Markings leaf, mirror the
        // exact compiled generic Tattoo leaf catalogue into that UI slot.
        const bool is_togruta_context =
            container_has_exact_tag(
                *owned_tags,
                g_appearance_compatibility_tags[28]);

        std::size_t togruta_tattoo_added = 0;

        if (is_togruta_context &&
            container_has_exact_tag(
                *owned_tags,
                g_appearance_slot_tags[25]))
        {
            togruta_tattoo_added +=
                append_static_slot_range_raw(
                    17,
                    *output);
        }

        if (is_togruta_context &&
            container_has_exact_tag(
                *owned_tags,
                g_appearance_slot_tags[26]))
        {
            togruta_tattoo_added +=
                append_static_slot_range_raw(
                    18,
                    *output);
        }

        if (togruta_tattoo_added != 0 &&
            !g_togruta_tattoo_bridge_seen.exchange(
                true, std::memory_order_relaxed))
        {
            g_togruta_tattoo_bridge_added.store(
                togruta_tattoo_added,
                std::memory_order_release);
            g_togruta_tattoo_bridge_pending.store(
                true,
                std::memory_order_release);
        }

        const bool is_origin_catalogue =
            output_contains_any(
                *output,
                g_origin_anchor_ids);

        const bool hair_structure_event =
            is_origin_catalogue ||
            container_has_exact_tag(
                *owned_tags,
                g_hair_container_slot_tag) ||
            container_has_exact_tag(
                *owned_tags,
                g_appearance_slot_tags[27]) ||
            container_has_exact_tag(
                *owned_tags,
                g_appearance_slot_tags[28]);

        if (hair_structure_event)
        {
            try_graft_missing_hair_roots();
        }

        // Static slot dispatch. No learned cache, no second filter call, no
        // asset scan. A request for one exact leaf slot only receives the
        // compile-time list assigned to that slot.
        for (std::size_t slot_index = 0;
             slot_index < g_appearance_slot_tags.size();
             ++slot_index)
        {
            if (!container_has_exact_tag(
                    *owned_tags,
                    g_appearance_slot_tags[slot_index]))
            {
                continue;
            }

            const auto added =
                append_static_catalogue_for_slot(
                    slot_index,
                    *owned_tags,
                    *output);

            if (!g_static_slot_seen[slot_index].exchange(
                    true, std::memory_order_relaxed))
            {
                g_static_slot_added[slot_index].store(
                    added, std::memory_order_release);
                g_static_slot_pending[slot_index].store(
                    true, std::memory_order_release);
            }
        }

        // Universal head catalogue: 57 humanoid/alien faces + 17 genuine
        // Astromech Head.Mesh choices. Paint CPDs are no longer injected
        // here; they are exposed through nested native color slots.
        if (container_has_exact_tag(*owned_tags, g_face_slot_tag))
        {
            // Patch only exact statically-listed NPC head CPDs, before the user
            // can click them. This resolves known IDs directly; it does not
            // enumerate UObjects, components, actors, packages or the world.
            request_static_npc_face_sanitize_window();

            for (std::size_t i = 0; i < g_target_ids.size(); ++i)
            {
                if (array_contains(*output, g_target_ids[i]))
                {
                    continue;
                }

                output->Add(g_target_ids[i]);

                if (!g_seen_catalogue[i].exchange(
                        true, std::memory_order_relaxed))
                {
                    g_pending_catalogue[i].store(
                        true, std::memory_order_release);
                }
            }
        }

        // Hidden whole-species roots are added only to the game's own Origin
        // catalogue, recognized by the vanilla Human/Zabrak anchors.
        if (is_origin_catalogue)
        {
            for (std::size_t i = 0;
                 i < g_hidden_species_ids.size();
                 ++i)
            {
                if (array_contains(
                        *output,
                        g_hidden_species_ids[i]))
                {
                    continue;
                }

                output->Add(g_hidden_species_ids[i]);

                if (!g_seen_species_catalogue[i].exchange(
                        true, std::memory_order_relaxed))
                {
                    g_pending_species_catalogue[i].store(
                        true, std::memory_order_release);
                }
            }
        }
    }


    // -------------------------------------------------------------------------
    // Native Astromech visual mount
    // -------------------------------------------------------------------------
    //
    // The Astromech CPD is still equipped into the game's Humanoid Face.Mesh
    // slot so the catalogue/save/customization system remains vanilla.
    //
    // That managed component is NOT suitable as the visible head: the game
    // periodically recreates/resets it.  The tested stable solution is to hide
    // it and render an independent SkeletalMeshComponent clone instead.
    //
    // Tested winning transform:
    //   Astromech internal bone "Head" -> Humanoid "neck_02"
    //   RelativeRotation Pitch=-90, Yaw=177.5, Roll=180
    //   RelativeScale3D  = 0.60
    //
    // This implementation handles BOTH:
    //   * Char_Hero_*                         (real gameplay character)
    //   * BP_CustomizationProxyCharacter_C    (customizer preview)
    //
    // Normal gameplay path performs ZERO transform writes after a clone is
    // mounted. The fast 250 ms watch is bounded to live customizer roles and
    // handles creation/replacement/deactivation; gameplay Hero alone falls back
    // to the slow safety scan.

    using RC::Unreal::FProperty;
    using RC::Unreal::UFunction;

    struct FVector56
    {
        double X{};
        double Y{};
        double Z{};
    };

    struct FRotator56
    {
        double Pitch{};
        double Yaw{};
        double Roll{};
    };

    static_assert(sizeof(FVector56) == 0x18);
    static_assert(sizeof(FRotator56) == 0x18);

    constexpr FRotator56 kAstroCloneRotation{
        -90.0,
        177.5,
        180.0,
    };

    constexpr FVector56 kAstroCloneScale{
        0.60,
        0.60,
        0.60,
    };

    // EXP13 measured this exact solved local offset on the working clone when
    // attached to CharacterMesh0 / neck_02. It was stable across observed roles.
    // EXP20 CLEAN uses it directly so mounting does not wait for a pose/socket query.
    constexpr FVector56 kAstroCloneRelativeLocation{
        -47.74463793518224,
        2.0845759110755715,
        0.0,
    };

    constexpr FVector56 kAstroSuppressedSourceScale{
        0.001,
        0.001,
        0.001,
    };

    constexpr FVector56 kNativeFaceDefaultScale{
        1.0,
        1.0,
        1.0,
    };

    // EXP20 CLEAN visual scheduler.
    //
    // There is NO FindAllOf / global object-array discovery. A UObject creation
    // listener filters immediately to the exact Humanoid Head.Face.Mesh
    // SkeletalMeshComponent and stores only those pointers. Retry/material
    // watches operate solely on that captured pointer list.
    constexpr auto kVisualRebuildRetryPeriod =
        std::chrono::milliseconds{16};
    constexpr auto kVisualRebuildRetryWindow =
        std::chrono::milliseconds{1500};
    constexpr auto kVisualMaterialRetryPeriod =
        std::chrono::milliseconds{125};
    constexpr auto kVisualMaterialRetryWindow =
        std::chrono::seconds{3};
    constexpr auto kVisualListenerHoldWindow =
        std::chrono::seconds{2};
    constexpr auto kVisualSafetyFallbackPeriod =
        std::chrono::seconds{10};
    // EXP11: this watch is pointer-only (NO FindAllOf), so while an Astro
    // instance is active it can run near frame cadence and collapse an in-place
    // managed mesh swap before the 250 ms flash seen in EXP9.
    constexpr auto kVisualActiveWatchPeriod =
        std::chrono::milliseconds{16};
    // If AddComponentByClass returns null near the end of the normal retry
    // window, extend only a short burst instead of waiting for the next 5 s
    // fallback. EXP2 showed a returned-null followed by a ~4.5 s stall.
    constexpr auto kVisualFailureRetryExtension =
        std::chrono::milliseconds{1000};
    constexpr auto kTransientVisualGapGrace =
        std::chrono::milliseconds{500};

    enum class VisualOwnerKind
    {
        Other,
        Hero,
        Customizer,
        CustomizerPreview,
        Portrait,
        StoryCustomizer,
        PreviewActor,
    };

    struct VisualMountState
    {
        VisualOwnerKind kind{VisualOwnerKind::Other};
        UObject* owner{};
        UObject* clone_host{};
        UObject* source{};
        UObject* clone{};
        UObject* mesh{};
        UObject* parent{};
        std::chrono::steady_clock::time_point last_seen{};
        bool seen_this_scan{};
        bool active{};
        bool awaiting_materials{};
    };

    struct AstroMountOffsetCache
    {
        UObject* mesh{};
        FVector56 relative_location{};
    };

    std::vector<AstroMountOffsetCache> g_astro_mount_offsets{};

    std::vector<VisualMountState> g_visual_mounts{};

    // EXP20D.2: remember ONLY material IDs that this mod hid on an allowed
    // player/customizer Face.Mesh component. This lets a reused component
    // restore our own stale bits before a different head mesh is evaluated,
    // without ever rewriting unrelated material visibility.
    struct NpcFaceSectionMaskState
    {
        UObject* component{};
        UObject* mesh{};
        std::vector<std::int32_t> hidden_material_ids{};
    };

    std::vector<NpcFaceSectionMaskState> g_npc_face_section_masks{};
    std::vector<UObject*> g_npc_face_scope_skip_logged{};

    // EXP20 CLEAN no-scan discovery: managed Humanoid Face.Mesh components are
    // captured once when Unreal creates them. on_update only revisits these
    // pointers; there is no FindAllOf(SkeletalMeshComponent) anywhere.
    std::vector<UObject*> g_captured_face_sources{};
    std::mutex g_captured_face_sources_mutex{};

    UObject* g_stable_visual_clone_host{};
    UClass* g_skeletal_mesh_component_class{};

    std::atomic_bool g_visual_dirty{true};
    std::atomic_bool g_visual_rebuild_event{true};
    std::atomic_bool g_visual_listener_armed{true};
    std::atomic_bool g_visual_listener_registered{false};
    std::atomic_uint32_t g_visual_create_events{0};

    std::chrono::steady_clock::time_point g_visual_listener_hold_until{};
    std::chrono::steady_clock::time_point g_visual_rebuild_retry_until{};
    std::chrono::steady_clock::time_point g_visual_material_retry_until{};
    std::chrono::steady_clock::time_point g_next_visual_rebuild_retry{};
    std::chrono::steady_clock::time_point g_next_visual_material_retry{};
    std::chrono::steady_clock::time_point g_next_visual_active_watch{};
    std::chrono::steady_clock::time_point g_next_visual_fallback{};

    bool g_visual_rebuild_retry_pending{};
    bool g_visual_material_retry_pending{};
    bool g_visual_context_active{};
    bool g_native_visual_mount_ready{false};

    auto is_live_object(UObject* object) -> bool
    {
        return object != nullptr &&
               UObject::IsReal(object) &&
               !object->IsUnreachable();
    }

    auto string_contains(const RC::StringType& value,
                         const RC::Unreal::TCHAR* needle) -> bool
    {
        return value.find(needle) != RC::StringType::npos;
    }


    auto get_gameplay_tag_property(
        UObject* object,
        const RC::Unreal::TCHAR* property_name,
        GameplayTag& out) -> bool
    {
        if (!is_live_object(object))
        {
            return false;
        }

        auto* value =
            object->GetValuePtrByPropertyNameInChain<GameplayTag>(
                property_name);

        if (value == nullptr)
 {
            return false;
        }

        out = *value;
        return true;
    }

    auto get_fragments_array(UObject* part) -> TArray<UObject*>*
    {
        if (!is_live_object(part))
        {
            return nullptr;
        }

        return part->GetValuePtrByPropertyNameInChain<TArray<UObject*>>(
            STR("Fragments"));
    }

    auto find_loaded_exact_object(
        const RC::Unreal::TCHAR* exact_path) -> UObject*
    {
        if (exact_path == nullptr)
        {
            return nullptr;
        }

        auto* exact =
            RC::Unreal::UObjectGlobals::StaticFindObject<UObject*>(
                nullptr,
                nullptr,
                exact_path);

        return is_live_object(exact) ? exact : nullptr;
    }


    auto initialize_astromech_paint_resolver() -> bool
    {
        const auto result =
            find_unique_executable_pattern(
                g_runtime,
                kGetCustomizationPartDefinitionPatternBytes,
                kGetCustomizationPartDefinitionPatternExact);

        g_get_customization_part_definition_address =
            result.matches == 1
                ? result.address
                : 0;

        RC::Output::send<RC::LogLevel::Verbose>(
            STR("[TheseArentTheHeadsYoureLookingFor] astro_paint_resolver_init aob_matches={} ready={} purpose=native-color-slot-graft direct_head_instance=true\n"),
            result.matches,
            g_get_customization_part_definition_address != 0);

        return g_get_customization_part_definition_address != 0;
    }

    auto safe_resolve_customization_part_definition(
        const FPrimaryAssetId* id) noexcept -> UObject*
    {
        if (id == nullptr ||
            g_get_customization_part_definition_address == 0)
        {
            return nullptr;
        }

        const auto fn =
            reinterpret_cast<
                GetCustomizationPartDefinitionFromPartIdFunction>(
                    g_get_customization_part_definition_address);

#if defined(_MSC_VER)
        __try
        {
            return fn(id);
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            return nullptr;
        }
#else
        return fn(id);
#endif
    }

    auto initialize_astromech_direct_mesh_loader() -> bool
    {
        const auto result =
            find_unique_executable_pattern(
                g_runtime,
                kStaticLoadObjectPatternBytes,
                kStaticLoadObjectPatternExact);

        g_static_load_object_address =
            result.matches == 1
                ? result.address
                : 0;

        g_skeletal_mesh_asset_class =
            RC::Unreal::UObjectGlobals::StaticFindObject<UClass*>(
                nullptr,
                nullptr,
                STR("/Script/Engine.SkeletalMesh"));

        g_astromech_direct_loader_ready =
            g_static_load_object_address != 0 &&
            g_skeletal_mesh_asset_class != nullptr;

        RC::Output::send<RC::LogLevel::Verbose>(
            STR("[TheseArentTheHeadsYoureLookingFor] astro_direct_loader_init staticload_aob_matches={} skeletalmesh_class={} ready={} unique_mesh_paths={} world_scan=false component_scan=false geometry_source=exact-static-list persistent_raw_mesh_cache=false gc_safe=path-resolve-on-demand\n"),
            result.matches,
            g_skeletal_mesh_asset_class != nullptr,
            g_astromech_direct_loader_ready,
            kAstromechDirectMeshSpecs.size());

        return g_astromech_direct_loader_ready;
    }

    auto safe_static_load_astromech_mesh(
        const RC::Unreal::TCHAR* exact_path) noexcept -> UObject*
    {
        if (!g_astromech_direct_loader_ready ||
            exact_path == nullptr)
        {
            return nullptr;
        }

        const auto fn =
            reinterpret_cast<StaticLoadObjectFunction>(
                g_static_load_object_address);

#if defined(_MSC_VER)
        __try
        {
            return fn(
                g_skeletal_mesh_asset_class,
                nullptr,
                exact_path,
                nullptr,
                0,
                nullptr,
                true,
                nullptr);
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            return nullptr;
        }
#else
        return fn(
            g_skeletal_mesh_asset_class,
            nullptr,
            exact_path,
            nullptr,
            0,
            nullptr,
            true,
            nullptr);
#endif
    }

    auto direct_astromech_mesh_index(
        UObject* source_mesh) -> std::size_t
    {
        if (!is_live_object(source_mesh))
        {
            return kAstromechDirectMeshSpecs.size();
        }

        const auto full_name =
            source_mesh->GetFullName();

        for (std::size_t i = 0;
             i < kAstromechDirectMeshSpecs.size();
             ++i)
        {
            if (string_contains(
                    full_name,
                    kAstromechDirectMeshSpecs[i].object_name))
            {
                return i;
            }
        }

        return kAstromechDirectMeshSpecs.size();
    }

    auto validate_direct_astromech_mesh(
        UObject* object,
        std::size_t index) -> bool
    {
        if (!is_live_object(object) ||
            index >= kAstromechDirectMeshSpecs.size())
        {
            return false;
        }

        const auto full_name =
            object->GetFullName();

        return string_contains(full_name, STR("SkeletalMesh ")) &&
               string_contains(
                   full_name,
                   kAstromechDirectMeshSpecs[index].object_name);
    }

    auto ensure_direct_astromech_mesh_loaded(
        std::size_t index,
        bool log_success = true) -> UObject*
    {
        if (index >= kAstromechDirectMeshSpecs.size())
        {
            return nullptr;
        }

        const auto& spec =
            kAstromechDirectMeshSpecs[index];

        // Exact registry lookup first. No C++ raw pointer survives a GC.
        auto* direct =
            RC::Unreal::UObjectGlobals::StaticFindObject<UObject*>(
                nullptr,
                nullptr,
                spec.object_path);

        if (!validate_direct_astromech_mesh(
                direct,
                index))
        {
            direct =
                safe_static_load_astromech_mesh(
                    spec.object_path);
        }

        if (!validate_direct_astromech_mesh(
                direct,
                index))
        {
            return nullptr;
        }

        if (log_success &&
            !g_astro_direct_gc_safe_load_logged.exchange(
                true,
                std::memory_order_relaxed))
        {
            RC::Output::send<RC::LogLevel::Verbose>(
                STR("[TheseArentTheHeadsYoureLookingFor] astro_direct_mesh_resolved index={} mesh={} persistence=component-owned raw_global_cache=false gc_safe=true no_scene_donor_required=true\n"),
                index,
                direct->GetFullName());
        }

        return direct;
    }

    auto prewarm_direct_astromech_meshes() -> std::size_t
    {
        if (!g_astromech_direct_loader_ready)
        {
            return 0;
        }

        std::size_t ready = 0;

        for (std::size_t i = 0;
             i < kAstromechDirectMeshSpecs.size();
             ++i)
        {
            auto* mesh =
                ensure_direct_astromech_mesh_loaded(
                    i,
                    false);

            if (validate_direct_astromech_mesh(mesh, i))
            {
                ++ready;
            }
        }

        g_astro_direct_prewarm_ready.store(
            ready,
            std::memory_order_release);

        if (!g_astro_direct_prewarm_logged.exchange(
                true,
                std::memory_order_acq_rel))
        {
            RC::Output::send<RC::LogLevel::Verbose>(
                STR("[TheseArentTheHeadsYoureLookingFor] astro_direct_prewarm ready={} total={} raw_pointer_cache=false geometry_source=exact-static-list\n"),
                ready,
                kAstromechDirectMeshSpecs.size());
        }

        return ready;
    }

    auto resolve_direct_astromech_visual_mesh(
        UObject* managed_source_mesh,
        bool& used_direct) -> UObject*
    {
        used_direct = false;

        const auto index =
            direct_astromech_mesh_index(
                managed_source_mesh);

        if (index >= kAstromechDirectMeshSpecs.size())
        {
            return nullptr;
        }

        auto* direct =
            ensure_direct_astromech_mesh_loaded(index);

        if (validate_direct_astromech_mesh(
                direct,
                index))
        {
            used_direct = true;
            return direct;
        }

        // EXP20 CLEAN never uses the game-managed mesh pointer as clone geometry.
        // If the exact static path is not ready yet, retry later.
        return nullptr;
    }

    auto astromech_rig_mask_from_mesh(
        UObject* mesh) -> std::uint64_t
    {
        if (!is_live_object(mesh))
        {
            return 0;
        }

        const auto full_name =
            mesh->GetFullName();

        if (string_contains(full_name, STR("/BR1/")))
        {
            return 1ULL << 7;
        }
        if (string_contains(full_name, STR("/R2/")))
        {
            return 1ULL << 8;
        }
        if (string_contains(full_name, STR("/R3/")))
        {
            return 1ULL << 9;
        }
        if (string_contains(full_name, STR("/R4/")))
        {
            return 1ULL << 10;
        }
        if (string_contains(full_name, STR("/R5/")))
        {
            return 1ULL << 11;
        }

        return 0;
    }

    auto find_fragment_by_slot(
        UObject* part,
        const GameplayTag& slot_tag) -> UObject*
    {
        if (slot_tag.tag_name.IsNone())
        {
            return nullptr;
        }

        auto* fragments = get_fragments_array(part);

        if (fragments == nullptr)
        {
            return nullptr;
        }

        for (auto* fragment : *fragments)
        {
            if (!is_live_object(fragment))
            {
                continue;
            }

            GameplayTag candidate_tag{};

            if (get_gameplay_tag_property(
                    fragment,
                    STR("SlotNameTag"),
                    candidate_tag) &&
                names_equal(
                    candidate_tag.tag_name,
                    slot_tag.tag_name))
            {
                return fragment;
            }
        }

        return nullptr;
    }

    auto duplicate_fragment_for_outer(
        UObject* source_fragment,
        UObject* destination_outer) -> UObject*
    {
        if (!is_live_object(source_fragment) ||
            !is_live_object(destination_outer))
        {
            return nullptr;
        }

        auto* fragment_class =
            source_fragment->GetClassPrivate();

        if (fragment_class == nullptr)
        {
            return nullptr;
        }

        // UE4SS exposes the engine's normal StaticConstructObject wrapper.
        // Construct a fresh fragment owned by the destination Appearance, then
        // copy only reflected properties from the Human slot template. This
        // deliberately avoids the EXP1/2 anti-pattern of storing the SAME
        // Human subobject pointer inside a Zabrak definition (wrong Outer).
        RC::Unreal::FStaticConstructObjectParameters params{
            fragment_class,
            destination_outer};

        auto* clone =
            RC::Unreal::UObjectGlobals::StaticConstructObject(
                params);

        if (!is_live_object(clone))
        {
            return nullptr;
        }

        for (FProperty* property :
             RC::Unreal::TFieldRange<FProperty>(
                 fragment_class,
                 RC::Unreal::EFieldIterationFlags::IncludeSuper |
                     RC::Unreal::EFieldIterationFlags::IncludeDeprecated))
        {
            if (property == nullptr)
            {
                continue;
            }

            auto* source_value =
                property->ContainerPtrToValuePtr<void>(
                    source_fragment);

            auto* destination_value =
                property->ContainerPtrToValuePtr<void>(
                    clone);

            if (source_value == nullptr ||
                destination_value == nullptr)
            {
                continue;
            }

            property->CopyCompleteValue(
                destination_value,
                source_value);
        }

        return clone;
    }


    auto request_astromech_paint_graft_window() -> void
    {
        g_astromech_paint_graft_requested.store(
            true, std::memory_order_release);
    }

    auto resolve_astromech_paint_source() -> UObject*
    {
        auto* source =
            find_loaded_exact_object(
                STR("/Game/Game/Customizations/Characters/Astromech/Appearance/CPD_AST_Appearance_Head.CPD_AST_Appearance_Head"));

        if (is_live_object(source))
        {
            return source;
        }

        return safe_resolve_customization_part_definition(
            &g_astromech_appearance_head_id);
    }

    struct AstromechPaintStructuralGraftOutcome
    {
        std::size_t eligible_roots{};
        std::size_t ready_roots{};
        std::size_t newly_patched_roots{};
        std::size_t added_slots{};
    };

    auto is_humanoid_head_structural_root(
        UObject* part) -> bool
    {
        if (!is_live_object(part))
        {
            return false;
        }

        const auto full_name =
            part->GetFullName();

        if (!string_contains(
                full_name,
                STR("/Game/Game/Customizations/Characters/")) ||
            string_contains(
                full_name,
                STR("/Astromech/")) ||
            !string_contains(
                full_name,
                STR("CPD_H_Appearance_Head_")))
        {
            return false;
        }

        constexpr std::array<const RC::Unreal::TCHAR*, 8>
            kNestedHeadContainerMarkers{{
            STR("CPD_H_Appearance_Head_Face_"),
            STR("CPD_H_Appearance_Head_Eyes_"),
            STR("CPD_H_Appearance_Head_Eyebrow_"),
            STR("CPD_H_Appearance_Head_Markings_"),
            STR("CPD_H_Appearance_Head_Skin"),
            STR("CPD_H_Appearance_Head_Tattoo"),
            STR("CPD_H_Appearance_Head_Scar"),
            STR("CPD_H_Appearance_Head_Freckles"),
        }};

        for (const auto* marker : kNestedHeadContainerMarkers)
        {
            if (string_contains(full_name, marker))
            {
                return false;
            }
        }

        return true;
    }

    auto try_graft_astromech_paint_slots()
        -> AstromechPaintStructuralGraftOutcome
    {
        AstromechPaintStructuralGraftOutcome outcome{};

        if (g_get_customization_part_definition_address == 0 ||
            g_astromech_head_color_primary_slot_tag.tag_name.IsNone() ||
            g_astromech_head_color_tertiary_slot_tag.tag_name.IsNone() ||
            g_astromech_head_color_quaternary_slot_tag.tag_name.IsNone())
        {
            return outcome;
        }

        auto* source =
            resolve_astromech_paint_source();

        if (!is_live_object(source))
        {
            return outcome;
        }

        auto* source_primary =
            find_fragment_by_slot(
                source,
                g_astromech_head_color_primary_slot_tag);
        auto* source_tertiary =
            find_fragment_by_slot(
                source,
                g_astromech_head_color_tertiary_slot_tag);
        auto* source_quaternary =
            find_fragment_by_slot(
                source,
                g_astromech_head_color_quaternary_slot_tag);

        if (!is_live_object(source_primary) ||
            !is_live_object(source_tertiary) ||
            !is_live_object(source_quaternary))
        {
            if (!g_astromech_paint_source_missing_logged.exchange(
                    true, std::memory_order_acq_rel))
            {
                RC::Output::send<RC::LogLevel::Warning>(
                    STR("[TheseArentTheHeadsYoureLookingFor] astro_paint_source_incomplete source=CPD_AST_Appearance_Head primary={} tertiary={} quaternary={} action=retry-bounded\n"),
                    is_live_object(source_primary),
                    is_live_object(source_tertiary),
                    is_live_object(source_quaternary));
            }
            return outcome;
        }

        if (!g_astromech_paint_source_logged.exchange(
                true, std::memory_order_acq_rel))
        {
            RC::Output::send<RC::LogLevel::Verbose>(
                STR("[TheseArentTheHeadsYoureLookingFor] astro_paint_source_ready source=CPD_AST_Appearance_Head slots=3 structural_mode=head-root-hoist slot_primary=Head.Color.Primary slot_tertiary=Head.Color.Tertiary slot_quaternary=Head.Color.Quaternary\n"));
        }

        std::vector<UObject*> roots{};
        roots.reserve(
            g_astromech_paint_humanoid_head_root_ids.size());

        // EXP11: resolve the five exact structural roots directly through the
        // game's CPD resolver. No FindAllOf and no dependency on the roots having
        // already appeared in the customizer scene. This is also intentionally
        // attempted during the startup retry window, before the UI asks Face.Mesh.
        outcome.eligible_roots =
            g_astromech_paint_humanoid_head_root_ids.size();

        for (std::size_t i = 0;
             i < g_astromech_paint_humanoid_head_root_ids.size();
             ++i)
        {
            auto* root =
                safe_resolve_customization_part_definition(
                    &g_astromech_paint_humanoid_head_root_ids[i]);

            if (is_live_object(root) &&
                is_humanoid_head_structural_root(root))
            {
                roots.push_back(root);
            }
        }

        if (!g_astromech_paint_structural_scan_seen.exchange(
                true,
                std::memory_order_relaxed))
        {
            RC::Output::send<RC::LogLevel::Verbose>(
                STR("[TheseArentTheHeadsYoureLookingFor] astro_paint_structural_resolve expected_roots={} resolved_roots={} periodic=false trigger=startup-or-pre-face-catalogue target=head-root-not-leaf exact_ids=true findallof=false\n"),
                outcome.eligible_roots,
                roots.size());
        }

        UObject* sources[3]{
            source_primary,
            source_tertiary,
            source_quaternary
        };

        const GameplayTag* tags[3]{
            &g_astromech_head_color_primary_slot_tag,
            &g_astromech_head_color_tertiary_slot_tag,
            &g_astromech_head_color_quaternary_slot_tag
        };

        for (auto* root : roots)
        {
            if (!is_humanoid_head_structural_root(root))
            {
                continue;
            }

            auto* fragments =
                get_fragments_array(root);

            if (fragments == nullptr)
            {
                continue;
            }

            std::size_t slots_ready = 0;
            std::size_t slots_added = 0;

            for (std::size_t slot = 0; slot < 3; ++slot)
            {
                if (is_live_object(
                        find_fragment_by_slot(
                            root,
                            *tags[slot])))
                {
                    ++slots_ready;
                    continue;
                }

                auto* owned_fragment =
                    duplicate_fragment_for_outer(
                        sources[slot],
                        root);

                if (!is_live_object(owned_fragment))
                {
                    continue;
                }

                fragments->Add(owned_fragment);
                ++slots_ready;
                ++slots_added;
            }

            if (slots_ready == 3)
            {
                ++outcome.ready_roots;
            }

            if (slots_added == 0)
            {
                continue;
            }

            ++outcome.newly_patched_roots;
            outcome.added_slots += slots_added;

            g_astromech_paint_structural_roots_patched.fetch_add(
                1,
                std::memory_order_acq_rel);

            RC::Output::send<RC::LogLevel::Verbose>(
                STR("[TheseArentTheHeadsYoureLookingFor] astro_paint_root_hoisted destination={} slots_ready={} slots_added={} hierarchy=head-root-siblings-of-face gating=active-astro-rig color_cpds=22\n"),
                root->GetFullName(),
                slots_ready,
                slots_added);
        }

        return outcome;
    }

    auto try_graft_astromech_paint_slots_immediate() -> void
    {
        const auto graft =
            try_graft_astromech_paint_slots();

        if (graft.newly_patched_roots != 0)
        {
            RC::Output::send<RC::LogLevel::Verbose>(
                STR("[TheseArentTheHeadsYoureLookingFor] astro_paint_pre_catalogue_graft expected_roots={} ready_roots={} newly_patched={} added_slots={} timing=before-vanilla-face-catalogue\n"),
                graft.eligible_roots,
                graft.ready_roots,
                graft.newly_patched_roots,
                graft.added_slots);
        }
    }

    auto try_graft_missing_hair_roots() -> void
    {
        if (g_zabrak_hair_graft_complete.load(
                std::memory_order_acquire) ||
            g_hair_container_slot_tag.tag_name.IsNone())
        {
            return;
        }

        auto* human_appearance =
            find_loaded_exact_object(
                STR("/Game/Game/Customizations/Characters/Human/CPD_H_Appearance_Human.CPD_H_Appearance_Human"));

        if (!is_live_object(human_appearance))
        {
            return;
        }

        auto* human_hair_fragment =
            find_fragment_by_slot(
                human_appearance,
                g_hair_container_slot_tag);

        if (!is_live_object(human_hair_fragment))
        {
            return;
        }

        for (const auto& spec : kHairRootGraftSpecs)
        {
            auto* appearance =
                find_loaded_exact_object(
                    spec.appearance_path);

            if (!is_live_object(appearance))
            {
                continue;
            }

            if (is_live_object(
                    find_fragment_by_slot(
                        appearance,
                        g_hair_container_slot_tag)))
            {
                g_zabrak_hair_graft_complete.store(
                    true, std::memory_order_release);
                continue;
            }

            auto* fragments =
                get_fragments_array(appearance);

            if (fragments == nullptr)
            {
                continue;
            }

            // Structural exception only. Clone the Human Hair slot fragment
            // INTO the Zabrak Appearance so GetOwningSlot/Outer-based runtime
            // logic sees a species-owned fragment. Never share the Human
            // subobject pointer between two CPD definitions.
            auto* owned_hair_fragment =
                duplicate_fragment_for_outer(
                    human_hair_fragment,
                    appearance);

            if (!is_live_object(owned_hair_fragment))
            {
                RC::Output::send<RC::LogLevel::Warning>(
                    STR("[TheseArentTheHeadsYoureLookingFor] hair_root_graft_failed species={} reason=construct-owned-fragment\n"),
                    spec.label);
                continue;
            }

            fragments->Add(owned_hair_fragment);

            g_zabrak_hair_graft_complete.store(
                true, std::memory_order_release);

            RC::Output::send<RC::LogLevel::Verbose>(
                STR("[TheseArentTheHeadsYoureLookingFor] hair_root_grafted species={} source=Human static_manifest=true policy=Zabrak-only ownership=destination-outer one_shot=true\n"),
                spec.label);
        }
    }

    auto zero_matching_tag(
        GameplayTag& tag,
        const GameplayTag& expected) -> bool
    {
        if (tag.tag_name.IsNone() ||
            expected.tag_name.IsNone() ||
            !names_equal(tag.tag_name, expected.tag_name))
        {
            return false;
        }

        // Keep the TArray allocation/layout intact and only turn the exact
        // GameplayTag entry into None. This avoids reallocating reflected
        // engine-owned arrays while making the override/hidden request inert.
        tag = GameplayTag{};
        return true;
    }


    auto zero_static_npc_hair_or_eyebrow_tag(
        GameplayTag& tag) -> bool
    {
        // 22 = Humanoid.Head.Eyebrow.Mesh
        // 28 = Hair.Hair.Mesh
        return zero_matching_tag(
                   tag,
                   g_appearance_slot_tags[22]) ||
               zero_matching_tag(
                   tag,
                   g_appearance_slot_tags[28]);
    }

    auto patch_static_npc_face_part(
        UObject* part,
        std::size_t target_index_value) -> bool
    {
        if (!is_live_object(part) ||
            target_index_value >= kHumanoidFaceTargetCount ||
            target_index_value >= kTargetSpecs.size() ||
            !kTargetSpecs[target_index_value].unlock_hair_and_eyebrows)
        {
            return false;
        }

        auto* fragments = get_fragments_array(part);

        if (fragments == nullptr)
        {
            return false;
        }

        std::uint32_t override_removed = 0;
        std::uint32_t locked_removed = 0;
        std::uint32_t hidden_removed = 0;

        for (auto* fragment : *fragments)
        {
            if (!is_live_object(fragment))
            {
                continue;
            }

            // FModel-backed Anakin rule generalized ONLY across the exact
            // compile-time NPC allowlist: free Hair.Hair.Mesh and
            // Humanoid.Head.Eyebrow.Mesh while preserving Scar, FacialHair,
            // species, name, morph and every unrelated authored restriction.
            if (auto* override_slots =
                    fragment->GetValuePtrByPropertyNameInChain<
                        TArray<GameplayTag>>(STR("OverrideSlots"));
                override_slots != nullptr)
            {
                for (auto& tag : *override_slots)
                {
                    if (zero_static_npc_hair_or_eyebrow_tag(tag))
                    {
                        ++override_removed;
                    }
                }
            }

            if (auto* locked_slots =
                    fragment->GetValuePtrByPropertyNameInChain<
                        TArray<GameplayTag>>(STR("LockedSlots"));
                locked_slots != nullptr)
            {
                for (auto& tag : *locked_slots)
                {
                    if (zero_static_npc_hair_or_eyebrow_tag(tag))
                    {
                        ++locked_removed;
                    }
                }
            }

            if (auto* hidden_slots =
                    fragment->GetValuePtrByPropertyNameInChain<
                        TArray<GameplayTag>>(STR("HiddenSlots"));
                hidden_slots != nullptr)
            {
                for (auto& tag : *hidden_slots)
                {
                    if (zero_static_npc_hair_or_eyebrow_tag(tag))
                    {
                        ++hidden_removed;
                    }
                }
            }
        }

        g_static_npc_face_override_tags_removed[target_index_value].store(
            override_removed, std::memory_order_release);
        g_static_npc_face_locked_tags_removed[target_index_value].store(
            locked_removed, std::memory_order_release);
        g_static_npc_face_hidden_tags_removed[target_index_value].store(
            hidden_removed, std::memory_order_release);
        g_static_npc_face_sanitize_done[target_index_value].store(
            true, std::memory_order_release);
        g_static_npc_face_sanitize_log_pending[target_index_value].store(
            true, std::memory_order_release);

        return true;
    }

    auto try_sanitize_static_npc_face_target(
        std::size_t target_index_value) -> bool
    {
        if (target_index_value >= kHumanoidFaceTargetCount ||
            target_index_value >= kTargetSpecs.size() ||
            !kTargetSpecs[target_index_value].unlock_hair_and_eyebrows)
        {
            return false;
        }

        if (g_static_npc_face_sanitize_done[target_index_value].load(
                std::memory_order_acquire))
        {
            return true;
        }

        auto* part =
            safe_resolve_customization_part_definition(
                &g_target_ids[target_index_value]);

        if (!is_live_object(part))
        {
            return false;
        }

        return patch_static_npc_face_part(
            part,
            target_index_value);
    }

    auto try_sanitize_static_npc_face_overrides() -> std::size_t
    {
        std::size_t newly_patched = 0;

        for (std::size_t i = 0;
             i < kHumanoidFaceTargetCount;
             ++i)
        {
            if (!kTargetSpecs[i].unlock_hair_and_eyebrows ||
                g_static_npc_face_sanitize_done[i].load(
                    std::memory_order_acquire))
            {
                continue;
            }

            if (try_sanitize_static_npc_face_target(i))
            {
                ++newly_patched;
            }
        }

        return newly_patched;
    }

    auto request_static_npc_face_sanitize_window() -> void
    {
        g_static_npc_face_sanitize_requested.store(
            true, std::memory_order_release);

        // Do the exact-ID work immediately as well; the bounded on_update
        // window only retries CPDs which were not resolvable yet.
        (void)try_sanitize_static_npc_face_overrides();
    }

    auto patch_devaronian_face_part(
        UObject* part,
        std::size_t spec_index) -> bool
    {
        if (!is_live_object(part) ||
            spec_index >= kDevaronianFacePatchSpecs.size())
        {
            return false;
        }

        auto* fragments = get_fragments_array(part);

        if (fragments == nullptr)
        {
            return false;
        }

        std::uint32_t override_removed = 0;
        std::uint32_t hidden_removed = 0;
        std::uint32_t invalid_removed = 0;

        for (auto* fragment : *fragments)
        {
            if (!is_live_object(fragment))
            {
                continue;
            }

            // Exact FModel-backed Devaronian face fix:
            //   Mxx suppresses Hair.Hair
            //   Fxx suppresses Hair.Facial
            // Strip only those exact slot tags. Any unrelated override remains.
            if (auto* override_slots =
                    fragment->GetValuePtrByPropertyNameInChain<
                        TArray<GameplayTag>>(STR("OverrideSlots"));
                override_slots != nullptr)
            {
                for (auto& tag : *override_slots)
                {
                    if (zero_matching_tag(
                            tag,
                            g_appearance_slot_tags[28]) ||
                        zero_matching_tag(
                            tag,
                            g_appearance_slot_tags[27]))
                    {
                        ++override_removed;
                    }
                }
            }

            if (auto* hidden_slots =
                    fragment->GetValuePtrByPropertyNameInChain<
                        TArray<GameplayTag>>(STR("HiddenSlots"));
                hidden_slots != nullptr)
            {
                for (auto& tag : *hidden_slots)
                {
                    if (zero_matching_tag(
                            tag,
                            g_hair_hair_parent_slot_tag) ||
                        zero_matching_tag(
                            tag,
                            g_hair_facial_parent_slot_tag))
                    {
                        ++hidden_removed;
                    }
                }
            }

            // FModel also exposes UI.CheckForInvalid.Devaronian on each
            // Devaronian face CPD. It is a face-owned negative/invalidation
            // signal and is the strongest concrete candidate for the observed
            // "same morph blocks helmet even on Human" behaviour.
            // Remove ONLY that guard; keep D01..D04 and Masculine/Femanine
            // identity tags intact. The EXP4 temporary owned-tag overlay stays
            // in place for positive compatibility/variant selection.
            if (auto* gameplay_tags =
                    fragment->GetValuePtrByPropertyNameInChain<
                        TArray<GameplayTag>>(STR("GameplayTags"));
                gameplay_tags != nullptr)
            {
                for (auto& tag : *gameplay_tags)
                {
                    if (zero_matching_tag(
                            tag,
                            g_devaronian_invalid_guard_tag))
                    {
                        ++invalid_removed;
                    }
                }
            }
        }

        g_devaronian_face_override_tags_removed[spec_index].store(
            override_removed, std::memory_order_release);
        g_devaronian_face_hidden_tags_removed[spec_index].store(
            hidden_removed, std::memory_order_release);
        g_devaronian_face_invalid_tags_removed[spec_index].store(
            invalid_removed, std::memory_order_release);
        g_devaronian_face_patch_done[spec_index].store(
            true, std::memory_order_release);
        g_devaronian_face_patch_log_pending[spec_index].store(
            true, std::memory_order_release);

        return true;
    }

    auto try_neutralize_loaded_devaronian_face_overrides()
        -> std::size_t
    {
        std::size_t newly_patched = 0;

        for (std::size_t i = 0;
             i < kDevaronianFacePatchSpecs.size();
             ++i)
        {
            if (g_devaronian_face_patch_done[i].load(
                    std::memory_order_acquire))
            {
                continue;
            }

            auto* part = find_loaded_exact_object(
                kDevaronianFacePatchSpecs[i].object_path);

            if (!is_live_object(part))
            {
                continue;
            }

            if (patch_devaronian_face_part(part, i))
            {
                ++newly_patched;
            }
        }

        return newly_patched;
    }

    auto request_devaronian_face_patch_window() -> void
    {
        // Cross-thread communication is atomic; retry timestamps are owned by
        // on_update. The synchronous exact-object attempt is valuable because
        // DoesPartMeetRequirements normally runs on the game/customization
        // path after the selected CPD has been resolved.
        g_devaronian_face_patch_requested.store(
            true, std::memory_order_release);

        (void)try_neutralize_loaded_devaronian_face_overrides();
    }

    auto visual_owner_kind(UObject* owner) -> VisualOwnerKind
    {
        if (!is_live_object(owner))
        {
            return VisualOwnerKind::Other;
        }

        const auto name = owner->GetFullName();

        if (string_contains(name, STR("Char_Hero_")))
        {
            return VisualOwnerKind::Hero;
        }

        if (string_contains(name, STR("BP_BrunoPortraitCharacter_C")))
        {
            return VisualOwnerKind::Portrait;
        }

        if (string_contains(name, STR("BP_CustomizationPreviewProxyCharacter_C")))
        {
            return VisualOwnerKind::CustomizerPreview;
        }

        if (string_contains(name, STR("BP_HawksCustomizationProxyCharacter_C")) ||
            string_contains(name, STR("BP_CustomCharacter_CustomizationProxy_C")))
        {
            return VisualOwnerKind::StoryCustomizer;
        }

        if (string_contains(name, STR("BP_PreviewActor_C")))
        {
            return VisualOwnerKind::PreviewActor;
        }

        if (string_contains(name, STR("BP_CustomizationProxyCharacter_C")))
        {
            return VisualOwnerKind::Customizer;
        }

        return VisualOwnerKind::Other;
    }

    auto visual_owner_label(VisualOwnerKind kind)
        -> const RC::Unreal::TCHAR*
    {
        switch (kind)
        {
        case VisualOwnerKind::Hero:
            return STR("HERO");
        case VisualOwnerKind::Customizer:
            return STR("CUSTOMIZER");
        case VisualOwnerKind::CustomizerPreview:
            return STR("CUSTOMIZER_PREVIEW");
        case VisualOwnerKind::Portrait:
            return STR("PORTRAIT");
        case VisualOwnerKind::StoryCustomizer:
            return STR("STORY_CUSTOMIZER");
        case VisualOwnerKind::PreviewActor:
            return STR("PREVIEW_ACTOR");
        default:
            return STR("OTHER");
        }
    }

    auto is_mc_face_cleanup_owner(VisualOwnerKind kind) -> bool
    {
        // Only the playable Hero and the known character-creator/portrait
        // proxies are allowed to receive embedded Hair/Eyebrow section edits.
        // World NPCs classify as Other; generic PreviewActor is deliberately
        // excluded as well.
        return kind == VisualOwnerKind::Hero ||
               kind == VisualOwnerKind::Customizer ||
               kind == VisualOwnerKind::CustomizerPreview ||
               kind == VisualOwnerKind::Portrait ||
               kind == VisualOwnerKind::StoryCustomizer;
    }

    auto uses_persistent_visual_role(VisualOwnerKind) -> bool
    {
        // EXP20 CLEAN clones stay owned by the same actor as their Face.Mesh source.
        // No preview/portrait clone is hosted on HERO, preventing ghost heads
        // after disposable proxy actors are destroyed.
        return false;
    }

    auto has_customizer_visual_state() -> bool
    {
        for (const auto& state : g_visual_mounts)
        {
            if (state.kind == VisualOwnerKind::Hero ||
                state.kind == VisualOwnerKind::Other)
            {
                continue;
            }

            if (state.active ||
                is_live_object(state.owner))
            {
                return true;
            }
        }

        return false;
    }


    auto has_active_astromech_visual_state() -> bool
    {
        for (const auto& state : g_visual_mounts)
        {
            if (!state.active)
            {
                continue;
            }

            if (is_live_object(state.clone) ||
                is_live_object(state.source))
            {
                return true;
            }
        }

        return false;
    }

    auto get_outer(UObject* object) -> UObject*
    {
        return is_live_object(object)
                   ? object->GetOuterPrivate()
                   : nullptr;
    }

    auto get_object_property(UObject* object,
                             const RC::Unreal::TCHAR* property_name)
        -> UObject*
    {
        if (!is_live_object(object))
        {
            return nullptr;
        }

        auto** value =
            object->GetValuePtrByPropertyNameInChain<UObject*>(
                property_name);

        return value != nullptr ? *value : nullptr;
    }

    auto get_fname_property(UObject* object,
                            const RC::Unreal::TCHAR* property_name,
                            FName& out) -> bool
    {
        if (!is_live_object(object))
        {
            return false;
        }

        auto* value =
            object->GetValuePtrByPropertyNameInChain<FName>(
                property_name);

        if (value == nullptr)
        {
            return false;
        }

        out = *value;
        return true;
    }

    auto get_vector_property(UObject* object,
                              const RC::Unreal::TCHAR* property_name,
                              FVector56& out) -> bool
    {
        if (!is_live_object(object))
        {
            return false;
        }

        auto* value =
            object->GetValuePtrByPropertyNameInChain<FVector56>(
                property_name);

        if (value == nullptr)
        {
            return false;
        }

        out = *value;
        return true;
    }

    auto find_cached_mount_offset(UObject* mesh)
        -> const FVector56*
    {
        if (!is_live_object(mesh))
        {
            return nullptr;
        }

        for (const auto& cached : g_astro_mount_offsets)
        {
            if (cached.mesh == mesh)
            {
                return &cached.relative_location;
            }
        }

        return nullptr;
    }

    auto remember_mount_offset(UObject* mesh,
                               const FVector56& relative_location)
        -> void
    {
        if (!is_live_object(mesh))
        {
            return;
        }

        for (auto& cached : g_astro_mount_offsets)
        {
            if (cached.mesh == mesh)
            {
                cached.relative_location =
                    relative_location;
                return;
            }
        }

        g_astro_mount_offsets.push_back(
            AstroMountOffsetCache{
                .mesh = mesh,
                .relative_location = relative_location,
            });
    }

    auto is_character_mesh_parent(UObject* component) -> bool
    {
        auto* parent = get_object_property(component, STR("AttachParent"));

        return is_live_object(parent) &&
               string_contains(parent->GetFullName(),
                               STR("CharacterMesh0"));
    }

    auto is_managed_humanoid_face_component(UObject* component) -> bool
    {
        if (!is_live_object(component))
        {
            return false;
        }

        const auto name = component->GetFullName();

        return string_contains(
                   name,
                   STR("br_Customization_Slot_Character_Appearance_Humanoid_Head_Face_Mesh")) ||
               string_contains(
                   name,
                   STR("br.Customization.Slot.Character.Appearance.Humanoid.Head.Face.Mesh"));
    }

    struct ReflectedCall
    {
        UFunction* function{};
        std::size_t byte_size{};
        std::vector<std::max_align_t> storage{};

        explicit ReflectedCall(UFunction* fn)
            : function(fn)
        {
            if (function == nullptr)
            {
                return;
            }

            byte_size =
                static_cast<std::size_t>(
                    function->GetParmsSize());

            if (byte_size == 0)
            {
                return;
            }

            const auto element_size =
                sizeof(std::max_align_t);

            storage.resize(
                (byte_size + element_size - 1) /
                element_size);

            function->InitializeStruct(storage.data());
        }

        ~ReflectedCall()
        {
            if (function != nullptr &&
                byte_size != 0 &&
                !storage.empty())
            {
                function->DestroyStruct(storage.data());
            }
        }

        auto data() -> void*
        {
            return storage.empty()
                       ? nullptr
                       : storage.data();
        }
    };

    auto input_property_at(UFunction* function,
                           std::size_t wanted_index)
        -> FProperty*
    {
        if (function == nullptr)
        {
            return nullptr;
        }

        std::size_t current_index = 0;

        for (FProperty* property :
             RC::Unreal::TFieldRange<FProperty>(
                 function,
                 RC::Unreal::EFieldIterationFlags::IncludeDeprecated))
        {
            if (!property->HasAnyPropertyFlags(
                    RC::Unreal::EPropertyFlags::CPF_Parm))
            {
                continue;
            }

            if (property->HasAnyPropertyFlags(
                    RC::Unreal::EPropertyFlags::CPF_ReturnParm))
            {
                continue;
            }

            // IMPORTANT:
            // UE reflection marks const-reference inputs such as
            // AddComponentByClass(..., const FTransform& RelativeTransform, ...)
            // as OutParm + ConstParm/ReferenceParm.  v0.7.2 skipped every
            // OutParm, so RelativeTransform vanished from the input list and
            // input index 2 incorrectly resolved to the final bool parameter.
            //
            // Skip only PURE output parameters. Keep const-reference inputs.
            const bool is_out =
                property->HasAnyPropertyFlags(
                    RC::Unreal::EPropertyFlags::CPF_OutParm);

            const bool is_const =
                property->HasAnyPropertyFlags(
                    RC::Unreal::EPropertyFlags::CPF_ConstParm);

            if (is_out && !is_const)
            {
                continue;
            }

            if (current_index == wanted_index)
            {
                return property;
            }

            ++current_index;
        }

        return nullptr;
    }

    template <typename T>
    auto set_input(UFunction* function,
                   void* params,
                   std::size_t index,
                   const T& value) -> bool
    {
        if (params == nullptr)
        {
            return false;
        }

        auto* property = input_property_at(function, index);

        if (property == nullptr)
        {
            return false;
        }

        auto* destination =
            property->ContainerPtrToValuePtr<void>(params);

        if (destination == nullptr)
        {
            return false;
        }

        property->CopyCompleteValue(destination, &value);
        return true;
    }

    template <typename T>
    auto read_return(UFunction* function,
                     void* params,
                     T& out) -> bool
    {
        if (function == nullptr || params == nullptr)
        {
            return false;
        }

        auto* property = function->GetReturnProperty();

        if (property == nullptr)
        {
            return false;
        }

        auto* source =
            property->ContainerPtrToValuePtr<void>(params);

        if (source == nullptr)
        {
            return false;
        }

        property->CopyCompleteValue(&out, source);
        return true;
    }

    auto copy_return_to_input(UFunction* source_function,
                              void* source_params,
                              UFunction* target_function,
                              void* target_params,
                              std::size_t target_input_index) -> bool
    {
        if (source_function == nullptr ||
            source_params == nullptr ||
            target_function == nullptr ||
            target_params == nullptr)
        {
            return false;
        }

        auto* source_property =
            source_function->GetReturnProperty();

        auto* target_property =
            input_property_at(
                target_function,
                target_input_index);

        if (source_property == nullptr ||
            target_property == nullptr)
        {
            return false;
        }

        // We intentionally do not interpret FTransform here. The source
        // K2_GetComponentToWorld return property and AddComponentByClass
        // RelativeTransform input property are both the engine's FTransform
        // script struct, so let Unreal's reflected property implementation
        // perform the copy.
        if (source_property->GetSize() !=
            target_property->GetSize())
        {
            RC::Output::send<RC::LogLevel::Error>(
                STR("[TheseArentTheHeadsYoureLookingFor] reflected-copy-size-mismatch source_size={} target_size={}\n"),
                source_property->GetSize(),
                target_property->GetSize());
            return false;
        }

        auto* source_value =
            source_property->ContainerPtrToValuePtr<void>(
                source_params);

        auto* target_value =
            target_property->ContainerPtrToValuePtr<void>(
                target_params);

        if (source_value == nullptr ||
            target_value == nullptr)
        {
            return false;
        }

        target_property->CopyCompleteValue(
            target_value,
            source_value);

        return true;
    }

    auto find_function(UObject* object,
                       const RC::Unreal::TCHAR* name)
        -> UFunction*
    {
        return is_live_object(object)
                   ? object->GetFunctionByNameInChain(name)
                   : nullptr;
    }

    auto call_return_object(UObject* object,
                            const RC::Unreal::TCHAR* function_name)
        -> UObject*
    {
        auto* function = find_function(object, function_name);

        if (function == nullptr)
        {
            return nullptr;
        }

        ReflectedCall call{function};
        object->ProcessEvent(function, call.data());

        UObject* result{};
        read_return(function, call.data(), result);
        return result;
    }

    auto call_return_int(UObject* object,
                         const RC::Unreal::TCHAR* function_name,
                         std::int32_t& out) -> bool
    {
        auto* function = find_function(object, function_name);

        if (function == nullptr)
        {
            return false;
        }

        ReflectedCall call{function};
        object->ProcessEvent(function, call.data());
        return read_return(function, call.data(), out);
    }

    auto get_skeletal_mesh(UObject* component) -> UObject*
    {
        if (auto* mesh =
                call_return_object(component,
                                   STR("GetSkeletalMeshAsset"));
            is_live_object(mesh))
        {
            return mesh;
        }

        if (auto* mesh =
                get_object_property(component,
                                    STR("SkeletalMeshAsset"));
            is_live_object(mesh))
        {
            return mesh;
        }

        return get_object_property(component, STR("SkeletalMesh"));
    }

    auto is_astromech_head_mesh(UObject* mesh) -> bool
    {
        if (!is_live_object(mesh))
        {
            return false;
        }

        const auto name = mesh->GetFullName();

        return string_contains(name, STR("/Droid/Astromech/")) &&
               string_contains(name, STR("Head"));
    }

    auto call_bool_bool(UObject* object,
                        const RC::Unreal::TCHAR* function_name,
                        bool a,
                        bool b) -> bool
    {
        auto* function = find_function(object, function_name);

        if (function == nullptr)
        {
            return false;
        }

        ReflectedCall call{function};

        if (!set_input(function, call.data(), 0, a) ||
            !set_input(function, call.data(), 1, b))
        {
            return false;
        }

        object->ProcessEvent(function, call.data());
        return true;
    }

    auto set_component_visibility(UObject* component,
                                  bool visible) -> void
    {
        if (!is_live_object(component))
        {
            return;
        }

        call_bool_bool(component,
                       STR("SetVisibility"),
                       visible,
                       true);

        call_bool_bool(component,
                       STR("SetHiddenInGame"),
                       !visible,
                       true);
    }

    auto set_component_tick(UObject* component,
                            bool enabled) -> void
    {
        auto* function =
            find_function(component,
                          STR("SetComponentTickEnabled"));

        if (function == nullptr)
        {
            return;
        }

        ReflectedCall call{function};

        if (set_input(function, call.data(), 0, enabled))
        {
            component->ProcessEvent(function, call.data());
        }
    }

    auto set_collision_disabled(UObject* component) -> void
    {
        auto* function =
            find_function(component, STR("SetCollisionEnabled"));

        if (function == nullptr)
        {
            return;
        }

        ReflectedCall call{function};
        const std::uint8_t no_collision = 0;

        if (set_input(
                function,
                call.data(),
                0,
                no_collision))
        {
            component->ProcessEvent(function, call.data());
        }
    }

    auto set_skeletal_mesh(UObject* component,
                           UObject* mesh) -> bool
    {
        if (!is_live_object(component) ||
            !is_live_object(mesh))
        {
            return false;
        }

        auto* function =
            find_function(component,
                          STR("SetSkeletalMeshAsset"));

        if (function == nullptr)
        {
            return false;
        }

        ReflectedCall call{function};

        if (!set_input(function,
                       call.data(),
                       0,
                       mesh))
        {
            return false;
        }

        component->ProcessEvent(function, call.data());
        return true;
    }

    auto get_num_materials(UObject* component) -> std::int32_t
    {
        std::int32_t result{};

        if (!call_return_int(component,
                             STR("GetNumMaterials"),
                             result))
        {
            return 0;
        }

        return result;
    }

    auto get_material(UObject* component,
                      std::int32_t index) -> UObject*
    {
        auto* function =
            find_function(component, STR("GetMaterial"));

        if (function == nullptr)
        {
            return nullptr;
        }

        ReflectedCall call{function};

        if (!set_input(function,
                       call.data(),
                       0,
                       index))
        {
            return nullptr;
        }

        component->ProcessEvent(function, call.data());

        UObject* material{};
        read_return(function, call.data(), material);
        return material;
    }

    auto show_material_section(UObject* component,
                               std::int32_t material_id,
                               bool show,
                               std::int32_t lod_index) -> bool
    {
        if (!is_live_object(component))
        {
            return false;
        }

        auto* function =
            find_function(component, STR("ShowMaterialSection"));

        if (function == nullptr)
        {
            return false;
        }

        ReflectedCall call{function};
        const std::int32_t direct_material_index = -1;

        if (!set_input(function, call.data(), 0, material_id) ||
            !set_input(function, call.data(), 1, direct_material_index) ||
            !set_input(function, call.data(), 2, show) ||
            !set_input(function, call.data(), 3, lod_index))
        {
            return false;
        }

        component->ProcessEvent(function, call.data());
        return true;
    }

    auto is_embedded_hair_material(UObject* material) -> bool
    {
        if (!is_live_object(material))
        {
            return false;
        }

        const auto name = material->GetFullName();

        // FModel proof for Anakin: MI_Anakin_Hair is a dedicated section in
        // the head SkeletalMesh itself. Keep the matcher material-local and
        // intentionally avoid "Hairline" skin/detail materials.
        return !string_contains(name, STR("Hairline")) &&
               !string_contains(name, STR("hairline")) &&
               (string_contains(name, STR("_Hair")) ||
                string_contains(name, STR("Hair_")) ||
                string_contains(name, STR(" Hair")) ||
                string_contains(name, STR("_hair")) ||
                string_contains(name, STR("hair_")));
    }

    auto is_embedded_eyebrow_material(UObject* material) -> bool
    {
        if (!is_live_object(material))
        {
            return false;
        }

        const auto name = material->GetFullName();

        return string_contains(name, STR("Eyebrow")) ||
               string_contains(name, STR("eyebrow")) ||
               string_contains(name, STR("_Brows")) ||
               string_contains(name, STR("_Brow")) ||
               string_contains(name, STR("_brows")) ||
               string_contains(name, STR("_brow"));
    }

    auto find_npc_face_section_mask_state(UObject* component)
        -> NpcFaceSectionMaskState*
    {
        for (auto& state : g_npc_face_section_masks)
        {
            if (state.component == component)
            {
                return &state;
            }
        }

        return nullptr;
    }

    auto find_or_create_npc_face_section_mask_state(UObject* component)
        -> NpcFaceSectionMaskState&
    {
        if (auto* state = find_npc_face_section_mask_state(component);
            state != nullptr)
        {
            return *state;
        }

        g_npc_face_section_masks.push_back(
            NpcFaceSectionMaskState{
                .component = component,
            });

        return g_npc_face_section_masks.back();
    }

    auto restore_our_npc_face_section_bits(
        NpcFaceSectionMaskState& state) -> std::int32_t
    {
        if (!is_live_object(state.component) ||
            state.hidden_material_ids.empty())
        {
            state.hidden_material_ids.clear();
            return 0;
        }

        std::int32_t restored = 0;

        for (const auto material_id : state.hidden_material_ids)
        {
            if (show_material_section(
                    state.component,
                    material_id,
                    true,
                    0))
            {
                ++restored;
            }
        }

        state.hidden_material_ids.clear();
        return restored;
    }

    auto log_npc_face_scope_skip_once(
        UObject* component,
        UObject* mesh,
        VisualOwnerKind kind) -> void
    {
        if (!is_live_object(component))
        {
            return;
        }

        if (std::find(
                g_npc_face_scope_skip_logged.begin(),
                g_npc_face_scope_skip_logged.end(),
                component) != g_npc_face_scope_skip_logged.end())
        {
            return;
        }

        // Audit dedupe for already event-captured Face.Mesh pointers only.
        // It does not discover/enumerate UObjects, actors, components or world.
        g_npc_face_scope_skip_logged.push_back(component);

        RC::Output::send<RC::LogLevel::Verbose>(
            STR("[TheseArentTheHeadsYoureLookingFor] npc_face_section_scope_skip owner={} owner_scope=non-mc action=no-ShowMaterialSection component={} mesh={} mc_only=true lod=0 findallof=false world_enum=false\n"),
            visual_owner_label(kind),
            component->GetFullName(),
            mesh->GetFullName());
    }

    // Return -1 while materials are not ready, 0 for a normal face with no
    // embedded hair/brow sections, or the number of hidden material sections.
    // EXP20D.2 is deliberately surgical:
    //   * only known MC/customizer/portrait owners are eligible;
    //   * Other + PreviewActor receive ZERO ShowMaterialSection calls;
    //   * only Hair/Eyebrow material IDs are ever hidden;
    //   * only LOD0 is touched (the material-ID layout we actually know);
    //   * when a component is reused, only IDs previously hidden by this mod
    //     are restored to visible. Unrelated Eyes/Head/Teeth/etc. are never
    //     rewritten.
    auto apply_embedded_npc_face_section_policy(
        UObject* component,
        UObject* mesh,
        VisualOwnerKind owner_kind) -> std::int32_t
    {
        if (!is_live_object(component) ||
            !is_live_object(mesh))
        {
            return 0;
        }

        if (!is_mc_face_cleanup_owner(owner_kind))
        {
            log_npc_face_scope_skip_once(
                component,
                mesh,
                owner_kind);
            return 0;
        }

        auto* previous_state =
            find_npc_face_section_mask_state(component);

        // If this exact Face.Mesh component switched to another SkeletalMesh,
        // clear ONLY visibility bits previously set by us. Do it before waiting
        // for the new material list so a stale material ID cannot temporarily
        // hide an Eye/Head/etc. section on the replacement.
        if (previous_state != nullptr &&
            previous_state->mesh != mesh)
        {
            const auto restored =
                restore_our_npc_face_section_bits(*previous_state);

            if (restored > 0)
            {
                RC::Output::send<RC::LogLevel::Verbose>(
                    STR("[TheseArentTheHeadsYoureLookingFor] npc_face_embedded_sections_restore owner={} component={} restored={} policy=own-bits-only lod=0 unrelated_materials_untouched=true\n"),
                    visual_owner_label(owner_kind),
                    component->GetFullName(),
                    restored);
            }

            previous_state->mesh = mesh;
        }

        const auto material_count =
            get_num_materials(component);

        if (material_count <= 0)
        {
            return -1;
        }

        std::vector<std::int32_t> target_material_ids{};
        std::int32_t hair_count = 0;
        std::int32_t eyebrow_count = 0;

        for (std::int32_t index = 0;
             index < material_count;
             ++index)
        {
            auto* material = get_material(component, index);

            const bool hair =
                is_embedded_hair_material(material);
            const bool eyebrow =
                is_embedded_eyebrow_material(material);

            if (!hair && !eyebrow)
            {
                continue;
            }

            target_material_ids.push_back(index);
            hair_count += hair ? 1 : 0;
            eyebrow_count += eyebrow ? 1 : 0;
        }

        if (previous_state != nullptr &&
            previous_state->mesh == mesh &&
            previous_state->hidden_material_ids != target_material_ids)
        {
            (void)restore_our_npc_face_section_bits(*previous_state);
        }

        if (target_material_ids.empty())
        {
            if (previous_state != nullptr)
            {
                previous_state->mesh = mesh;
            }
            return 0;
        }

        auto& state =
            find_or_create_npc_face_section_mask_state(component);
        state.mesh = mesh;

        std::int32_t hidden_count = 0;

        // Never loop over non-target material IDs. Eyes, EyeAO, Eyelashes,
        // Head, Teeth, Fluid, etc. receive no visibility write here.
        for (const auto material_id : target_material_ids)
        {
            if (show_material_section(
                    component,
                    material_id,
                    false,
                    0))
            {
                ++hidden_count;
            }
        }

        state.hidden_material_ids = target_material_ids;

        RC::Output::send<RC::LogLevel::Verbose>(
            STR("[TheseArentTheHeadsYoureLookingFor] npc_face_embedded_sections owner={} mesh={} hair_hidden={} eyebrow_hidden={} hidden_calls={} materials={} lod=0 policy=hair-eyebrow-only mc_only=true unrelated_materials_untouched=true source=event-captured-Face.Mesh findallof=false world_enum=false\n"),
            visual_owner_label(owner_kind),
            mesh->GetFullName(),
            hair_count,
            eyebrow_count,
            hidden_count,
            material_count);

        return hidden_count;
    }

    auto set_material(UObject* component,
                      std::int32_t index,
                      UObject* material) -> bool
    {
        if (!is_live_object(material))
        {
            return false;
        }

        auto* function =
            find_function(component, STR("SetMaterial"));

        if (function == nullptr)
        {
            return false;
        }

        ReflectedCall call{function};

        if (!set_input(function, call.data(), 0, index) ||
            !set_input(function, call.data(), 1, material))
        {
            return false;
        }

        component->ProcessEvent(function, call.data());
        return true;
    }

    auto copy_materials(UObject* source,
                        UObject* clone) -> std::int32_t
    {
        const auto count = get_num_materials(source);

        for (std::int32_t index = 0;
             index < count;
             ++index)
        {
            auto* material = get_material(source, index);

            if (is_live_object(material))
            {
                set_material(clone, index, material);
            }
        }

        return count;
    }

    auto sync_materials_if_changed(
        UObject* source,
        UObject* direct_instance) -> std::int32_t
    {
        if (!is_live_object(source) ||
            !is_live_object(direct_instance))
        {
            return 0;
        }

        const auto count =
            get_num_materials(source);

        if (count <= 0)
        {
            return 0;
        }

        for (std::int32_t index = 0;
             index < count;
             ++index)
        {
            auto* source_material =
                get_material(source, index);

            if (!is_live_object(source_material))
            {
                continue;
            }

            auto* current_material =
                get_material(direct_instance, index);

            if (current_material != source_material)
            {
                set_material(
                    direct_instance,
                    index,
                    source_material);
            }
        }

        return count;
    }

    auto get_num_bones(UObject* component) -> std::int32_t
    {
        std::int32_t result{};

        if (!call_return_int(component,
                             STR("GetNumBones"),
                             result))
        {
            return 0;
        }

        return result;
    }

    auto get_bone_name(UObject* component,
                       std::int32_t index,
                       FName& out) -> bool
    {
        auto* function =
            find_function(component, STR("GetBoneName"));

        if (function == nullptr)
        {
            return false;
        }

        ReflectedCall call{function};

        if (!set_input(function,
                       call.data(),
                       0,
                       index))
        {
            return false;
        }

        component->ProcessEvent(function, call.data());
        return read_return(function, call.data(), out);
    }

    auto find_exact_bone(UObject* component,
                         const RC::Unreal::TCHAR* wanted,
                         FName& out) -> bool
    {
        const auto count = get_num_bones(component);
        const FName wanted_name(wanted, RC::Unreal::FNAME_Find);

        if (wanted_name.IsNone())
        {
            return false;
        }

        for (std::int32_t index = 0;
             index < count;
             ++index)
        {
            FName candidate{};

            if (get_bone_name(component,
                              index,
                              candidate) &&
                names_equal(candidate, wanted_name))
            {
                out = candidate;
                return true;
            }
        }

        return false;
    }

