    auto attach_to_bone(UObject* component,
                        UObject* parent,
                        const FName& bone) -> bool
    {
        auto* function =
            find_function(component,
                          STR("K2_AttachToComponent"));

        if (function == nullptr)
        {
            return false;
        }

        ReflectedCall call{function};

        const std::uint8_t snap_to_target = 2;
        const bool no_weld = false;

        if (!set_input(function, call.data(), 0, parent) ||
            !set_input(function, call.data(), 1, bone) ||
            !set_input(function,
                       call.data(),
                       2,
                       snap_to_target) ||
            !set_input(function,
                       call.data(),
                       3,
                       snap_to_target) ||
            !set_input(function,
                       call.data(),
                       4,
                       snap_to_target) ||
            !set_input(function,
                       call.data(),
                       5,
                       no_weld))
        {
            return false;
        }

        component->ProcessEvent(function, call.data());
        return true;
    }

